var textForPages =["\u041d\u043e\u0432\u043e\u0441\u0442\u043d\u043e\u0439 \u0434\u0430\u0439\u0434\u0436\u0435\u0441\u0442 3\u201310 \u0430\u043f\u0440\u0435\u043b\u044f 2026 \u0433\u043e\u0434\u0430\u000d\u000a\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u000d\u000a\u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439\u000d\u000a\u0413\u043b\u0430\u0432\u043d\u043e\u0435 \u0432 \u0432\u044b\u043f\u0443\u0441\u043a\u0435\u000d\u000a\u0420\u043e\u0441\u0441\u0438\u044f \u0438 \u041a\u0438\u0442\u0430\u0439 \u0437\u0430\u0431\u043b\u043e\u043a\u0438\u0440\u043e\u0432\u0430\u043b\u0438 \u000d\u000a\u0440\u0435\u0437\u043e\u043b\u044e\u0446\u0438\u044e \u041e\u041e\u041d \u043f\u043e \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u043e\u043c\u0443 \u043f\u0440\u043e\u043b\u0438\u0432\u0443 \u000d\u000a\u0412\u0435\u0442\u043e \u043d\u0430\u043b\u043e\u0436\u0438\u043b\u0438 \u043d\u0430 \u0441\u043b\u0435\u0434\u0443\u044e\u0449\u0438\u0439 \u0434\u0435\u043d\u044c \u043f\u043e\u0441\u043b\u0435 \u000d\u000a\u043f\u0435\u0440\u0435\u043c\u0438\u0440\u0438\u044f \u2014 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442, \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u0430\u043d\u043d\u044b\u0439 \u2028\u000d\u000a11 \u0438\u0437 15 \u0447\u043b\u0435\u043d\u043e\u0432 \u0421\u0411, \u043f\u0440\u0438\u0437\u044b\u0432\u0430\u043b \u0437\u0430\u0449\u0438\u0442\u0438\u0442\u044c \u0441\u0443\u0434\u043e\u0445\u043e\u0434\u0441\u0442\u0432\u043e \u000d\u000a\u0447\u0435\u0440\u0435\u0437 \u043a\u043b\u044e\u0447\u0435\u0432\u043e\u0439 \u043d\u0435\u0444\u0442\u044f\u043d\u043e\u0439 \u043c\u0430\u0440\u0448\u0440\u0443\u0442. \u041c\u043e\u0441\u043a\u0432\u0430 \u0438 \u000d\u000a\u041f\u0435\u043a\u0438\u043d \u043d\u0430\u0437\u0432\u0430\u043b\u0438 \u0435\u0433\u043e \u0430\u043d\u0442\u0438\u0438\u0440\u0430\u043d\u0441\u043a\u0438\u043c.\u000d\u000a\u0410\u043b\u044e\u043c\u0438\u043d\u0438\u0435\u0432\u044b\u0439 \u0437\u0430\u0432\u043e\u0434 EGA \u0432 \u0410\u0431\u0443-\u0414\u0430\u0431\u0438 \u000d\u000a\u043e\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d \u043f\u043e\u0441\u043b\u0435 \u0438\u0440\u0430\u043d\u0441\u043a\u043e\u0433\u043e \u0443\u0434\u0430\u0440\u0430 \u000d\u000a\u0417\u0430\u0432\u043e\u0434 Al Taweelah \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044c\u044e 1,6 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u0432 \u0433\u043e\u0434 \u000d\u000a\u043f\u0440\u0435\u043a\u0440\u0430\u0442\u0438\u043b \u0440\u0430\u0431\u043e\u0442\u0443. \u0417\u0430\u0432\u043e\u0434 Alba \u0432 \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0435 \u000d\u000a\u043f\u043e\u0432\u0440\u0435\u0436\u0434\u0435\u043d \u0438 \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442 \u043b\u0438\u0448\u044c \u043d\u0430 30% \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0438 \u2014 \u000d\u000a\u0440\u0435\u0433\u0438\u043e\u043d \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0438\u0432\u0430\u0435\u0442 9% \u043c\u0438\u0440\u043e\u0432\u043e\u0433\u043e \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u000d\u000a\u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f.\u000d\u000a\u0421\u0442\u0440\u0430\u043d\u044b \u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u0437\u0430\u043b\u0438\u0432\u0430 \u0438\u0449\u0443\u0442 \u000d\u000a\u0434\u0435\u0448\u0435\u0432\u044b\u0435 \u0443\u043a\u0440\u0430\u0438\u043d\u0441\u043a\u0438\u0435 \u0434\u0440\u043e\u043d\u044b\u043f\u0435\u0440\u0435\u0445\u0432\u0430\u0442\u0447\u0438\u043a\u0438 \u000d\u000a\u0418\u0440\u0430\u043d \u0432\u044b\u043f\u0443\u0441\u0442\u0438\u043b \u043f\u043e \u0440\u0435\u0433\u0438\u043e\u043d\u0443 \u0431\u043e\u043b\u0435\u0435 3500 \u000d\u000a\u0431\u0435\u0441\u043f\u0438\u043b\u043e\u0442\u043d\u0438\u043a\u043e\u0432, \u0438\u0441\u0442\u043e\u0449\u0438\u0432 \u0437\u0430\u043f\u0430\u0441\u044b \u0434\u043e\u0440\u043e\u0433\u0438\u0445 \u0440\u0430\u043a\u0435\u0442 \u000d\u000aPatriot ($4 \u043c\u043b\u043d/\u0448\u0442.). \u0423\u043a\u0440\u0430\u0438\u043d\u0441\u043a\u0438\u0439 \u043f\u0435\u0440\u0435\u0445\u0432\u0430\u0442\u0447\u0438\u043a Terra \u000d\u000aA1 \u0441\u0442\u043e\u0438\u0442 $2500 \u2014 \u0438\u043d\u0442\u0435\u0440\u0435\u0441 \u0441\u043e \u0441\u0442\u043e\u0440\u043e\u043d\u044b \u041e\u0410\u042d \u000d\u000a\u0438 \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u043e\u0439 \u0410\u0440\u0430\u0432\u0438\u0438 \u0440\u0435\u0437\u043a\u043e \u0432\u044b\u0440\u043e\u0441.\u000d\u000a\u041a\u0438\u0442\u0430\u0439 \u043f\u0435\u0440\u0435\u043f\u0438\u0441\u044b\u0432\u0430\u0435\u0442 \u043f\u0440\u0430\u0432\u0438\u043b\u0430 \u043d\u0430 \u0440\u044b\u043d\u043a\u0435 \u000d\u000a\u0436\u0435\u043b\u0435\u0437\u043d\u043e\u0439 \u0440\u0443\u0434\u044b \u0437\u0430 $190 \u043c\u043b\u0440\u0434 \u000d\u000a\u0413\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u0442\u0440\u0435\u0439\u0434\u0435\u0440 CMRG \u0434\u043e\u0431\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u000d\u000a\u043e\u0442 BHP \u043f\u0435\u0440\u0435\u0445\u043e\u0434\u0430 \u043d\u0430 \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u0443\u044e \u043c\u043e\u0434\u0435\u043b\u044c \u000d\u000a\u0446\u0435\u043d\u043e\u043e\u0431\u0440\u0430\u0437\u043e\u0432\u0430\u043d\u0438\u044f. Rio Tinto \u0438 Fortescue \u0443\u0436\u0435 \u000d\u000a\u0441\u043e\u0433\u043b\u0430\u0441\u0438\u043b\u0438\u0441\u044c \u2014 \u0440\u0435\u0447\u044c \u0438\u0434\u0435\u0442 \u043e \u0441\u043c\u0435\u043d\u0435 \u0433\u043b\u043e\u0431\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u000d\u000a\u0446\u0435\u043d\u043e\u043e\u0431\u0440\u0430\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u044f.\u000d\u000aEVE Energy \u0432\u043b\u043e\u0436\u0438\u0442 $1,6 \u043c\u043b\u0440\u0434 \u0432 \u0434\u0432\u0430 \u043d\u043e\u0432\u044b\u0445 \u000d\u000a\u0430\u043a\u043a\u0443\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u043d\u044b\u0445 \u0437\u0430\u0432\u043e\u0434\u0430 \u000d\u000a\u0421\u0443\u043c\u043c\u0430\u0440\u043d\u0430\u044f \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044c \u2014 110 \u0413\u0412\u0442 \u0447. \u0421 \u0443\u0447\u0435\u0442\u043e\u043c \u000d\u000a\u043c\u0430\u0440\u0442\u043e\u0432\u0441\u043a\u0438\u0445 \u0430\u043d\u043e\u043d\u0441\u043e\u0432 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u043f\u043b\u0430\u043d\u0438\u0440\u0443\u0435\u0442 \u0437\u0430\u043f\u0443\u0441\u0442\u0438\u0442\u044c \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u043e\u0431\u0449\u0435\u0439 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044c\u044e 230 \u0413\u0412\u0442 \u0447 \u2014 \u000d\u000a\u043c\u0430\u0441\u0448\u0442\u0430\u0431\u043d\u0430\u044f \u0441\u0442\u0430\u0432\u043a\u0430 \u043d\u0430 \u0440\u043e\u0441\u0442 \u0441\u043f\u0440\u043e\u0441\u0430 \u043d\u0430 \u0431\u0430\u0442\u0430\u0440\u0435\u0438 \u0434\u043b\u044f \u000d\u000aEV \u0438 \u043d\u0430\u043a\u043e\u043f\u0438\u0442\u0435\u043b\u0438 \u044d\u043d\u0435\u0440\u0433\u0438\u0438.\u000d\u000a\u041f\u0435\u0440\u0435\u043c\u0438\u0440\u0438\u0435 \u0441 \u0418\u0440\u0430\u043d\u043e\u043c \u043f\u0440\u0438 \u043f\u043e\u0441\u0440\u0435\u0434\u043d\u0438\u0447\u0435\u0441\u0442\u0432\u0435 \u000d\u000a\u041a\u0438\u0442\u0430\u044f \u000d\u000a\u0422\u0440\u0430\u043c\u043f \u043f\u0440\u0438\u0437\u043d\u0430\u043b, \u0447\u0442\u043e \u041f\u0435\u043a\u0438\u043d \u0443\u0431\u0435\u0434\u0438\u043b \u0418\u0440\u0430\u043d \u0437\u0430\u043a\u043b\u044e\u0447\u0438\u0442\u044c \u000d\u000a\u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0435 \u043e \u043f\u0440\u0435\u043a\u0440\u0430\u0449\u0435\u043d\u0438\u0438 \u043e\u0433\u043d\u044f. \u041d\u043e\u0432\u043e\u0441\u0442\u044c \u043f\u0440\u0438\u0448\u043b\u0430 \u000d\u000a\u0437\u0430 \u0447\u0430\u0441\u044b \u0434\u043e \u0434\u0435\u0434\u043b\u0430\u0439\u043d\u0430, \u043f\u043e\u0441\u043b\u0435 \u043a\u043e\u0442\u043e\u0440\u043e\u0433\u043e \u0421\u0428\u0410 \u000d\u000a\u0433\u0440\u043e\u0437\u0438\u043b\u0438\u0441\u044c \u0443\u043d\u0438\u0447\u0442\u043e\u0436\u0438\u0442\u044c \u0446\u0438\u0432\u0438\u043b\u0438\u0437\u0430\u0446\u0438\u044e \u0432 \u0418\u0440\u0430\u043d\u0435.\u000d\u000aVale \u0434\u043e\u0441\u0440\u043e\u0447\u043d\u043e \u043e\u0441\u0442\u0430\u043d\u0430\u0432\u043b\u0438\u0432\u0430\u0435\u0442 \u0437\u0430\u0432\u043e\u0434\u044b \u000d\u000a\u0432 \u041e\u043c\u0430\u043d\u0435 \u0438\u0437-\u0437\u0430 \u0431\u043b\u043e\u043a\u0430\u0434\u044b \u041e\u0440\u043c\u0443\u0437\u0430 \u000d\u000a\u0411\u0440\u0430\u0437\u0438\u043b\u044c\u0441\u043a\u0430\u044f \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u043f\u0435\u0440\u0435\u043d\u0435\u0441\u043b\u0430 \u043f\u043b\u0430\u043d\u043e\u0432\u044b\u0439 \u000d\u000a\u0440\u0435\u043c\u043e\u043d\u0442 \u043d\u0430 \u0437\u0430\u0432\u043e\u0434\u0430\u0445 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044c\u044e 9 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u0432 \u0433\u043e\u0434 \u2014 \u000d\u000a\u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0438 \u0432 \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0443\u044e \u0410\u0440\u0430\u0432\u0438\u044e, \u041e\u0410\u042d \u0438 \u041a\u0430\u0442\u0430\u0440 \u000d\u000a\u0444\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u044b \u0431\u043b\u043e\u043a\u0430\u0434\u043e\u0439.\u000d\u000a\u041a\u0438\u0442\u0430\u0439 \u0441\u043e\u0437\u0434\u0430\u0435\u0442 \u044e\u0440\u0438\u0434\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u043c\u0435\u0445\u0430\u043d\u0438\u0437\u043c \u000d\u000a\u043f\u0440\u043e\u0442\u0438\u0432 \u0441\u0430\u043d\u043a\u0446\u0438\u0439 \u000d\u000a\u0413\u043e\u0441\u0441\u043e\u0432\u0435\u0442 \u041a\u041d\u0420 \u043f\u0440\u0438\u043d\u044f\u043b \u041f\u043e\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u043e \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e\u0441\u0442\u0438 \u000d\u000a\u0446\u0435\u043f\u043e\u0447\u0435\u043a \u043f\u043e\u0441\u0442\u0430\u0432\u043e\u043a \u2014 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442 \u0434\u0430\u0435\u0442 \u041f\u0435\u043a\u0438\u043d\u0443 \u000d\u000a\u043f\u0440\u0430\u0432\u043e\u0432\u0443\u044e \u0431\u0430\u0437\u0443 \u0434\u043b\u044f \u0441\u0438\u043c\u043c\u0435\u0442\u0440\u0438\u0447\u043d\u044b\u0445 \u043c\u0435\u0440 \u0432 \u0441\u0442\u043e\u0440\u043e\u043d\u0443 \u000d\u000a\u0441\u0442\u0440\u0430\u043d, \u0432\u0432\u043e\u0434\u044f\u0449\u0438\u0445 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u044f \u043f\u0440\u043e\u0442\u0438\u0432 \u041a\u0438\u0442\u0430\u044f, \u000d\u000a\u0432\u043a\u043b\u044e\u0447\u0430\u044f \u0441\u043f\u0435\u0446\u0442\u0430\u0440\u0438\u0444\u044b \u0438 \u0437\u0430\u043f\u0440\u0435\u0442 \u043d\u0430 \u0441\u0434\u0435\u043b\u043a\u0438.\u000d\u000a\u041a\u0438\u0442\u0430\u0439 \u043c\u043e\u0434\u0435\u0440\u043d\u0438\u0437\u0438\u0440\u0443\u0435\u0442 \u0430\u0444\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u0443\u044e \u000d\u000a\u0436\u0435\u043b\u0435\u0437\u043d\u0443\u044e \u0434\u043e\u0440\u043e\u0433\u0443 \u0437\u0430 $1,24 \u043c\u043b\u0440\u0434 \u000d\u000aCMOC \u0438 Zijin Mining \u0432\u043c\u0435\u0441\u0442\u0435 \u0441 \u0433\u043e\u0441\u043a\u043e\u0440\u043f\u043e\u0440\u0430\u0446\u0438\u0435\u0439 \u000d\u000aCCECC \u0440\u0435\u0430\u043d\u0438\u043c\u0438\u0440\u0443\u044e\u0442 1860 \u043a\u0438\u043b\u043e\u043c\u0435\u0442\u0440\u043e\u0432\u0443\u044e \u0432\u0435\u0442\u043a\u0443 \u000d\u000a\u0417\u0430\u043c\u0431\u0438\u044f \u2014 \u0422\u0430\u043d\u0437\u0430\u043d\u0438\u044f, \u043f\u043e\u0441\u0442\u0440\u043e\u0435\u043d\u043d\u0443\u044e \u043f\u0440\u0438 \u041c\u0430\u043e. \u0426\u0435\u043b\u044c \u2014 \u000d\u000a\u0432\u0437\u044f\u0442\u044c \u043f\u043e\u0434 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u043b\u043e\u0433\u0438\u0441\u0442\u0438\u043a\u0443 \u043a\u0440\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u000d\u000a\u043c\u0438\u043d\u0435\u0440\u0430\u043b\u043e\u0432 \u0432 \u043e\u0431\u0445\u043e\u0434 \u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u0438\u0445 \u0443\u0441\u0438\u043b\u0438\u0439.\u000d\u000a\u041c\u0430\u0440\u043e\u043a\u043a\u043e \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0440\u0443\u0435\u0442 \u0435\u0449\u0435 $850 \u043c\u043b\u043d \u000d\u000a\u0432 \u0442\u0440\u0430\u043d\u0441\u043f\u043e\u0440\u0442 \u043a \u0427\u041c 2030 \u000d\u000a151 \u043d\u043e\u0432\u044b\u0439 \u043f\u0440\u043e\u0435\u043a\u0442, \u0430\u043a\u0446\u0435\u043d\u0442 \u2014 \u043d\u0430 \u0432\u044b\u0441\u043e\u043a\u043e\u0441\u043a\u043e\u0440\u043e\u0441\u0442\u043d\u0443\u044e \u000d\u000a\u0436\u0435\u043b\u0435\u0437\u043d\u0443\u044e \u0434\u043e\u0440\u043e\u0433\u0443 \u043d\u0430 \u0441\u0435\u0432\u0435\u0440\u043e \u0437\u0430\u043f\u0430\u0434\u0435 \u0441\u0442\u0440\u0430\u043d\u044b. \u0412\u0441\u0435\u0433\u043e \u000d\u000a\u0432 \u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0443 \u043a \u0447\u0435\u043c\u043f\u0438\u043e\u043d\u0430\u0442\u0443 \u0443\u0436\u0435 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043e \u000d\u000a\u0441\u0432\u044b\u0448\u0435 $4,85 \u043c\u043b\u0440\u0434.\u000d\u000a01 09","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 3\u201310 \u0430\u043f\u0440\u0435\u043b\u044f 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430 #\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b\u000d\u000a\u0420\u043e\u0441\u0441\u0438\u044f \u0438 \u041a\u0438\u0442\u0430\u0439 \u0437\u0430\u0431\u043b\u043e\u043a\u0438\u0440\u043e\u0432\u0430\u043b\u0438 \u0431\u0430\u0445\u0440\u0435\u0439\u043d\u0441\u043a\u0443\u044e \u000d\u000a\u0440\u0435\u0437\u043e\u043b\u044e\u0446\u0438\u044e \u0421\u0411 \u041e\u041e\u041d \u043f\u043e \u0437\u0430\u0449\u0438\u0442\u0435 \u0441\u0443\u0434\u043e\u0445\u043e\u0434\u0441\u0442\u0432\u0430 \u000d\u000a\u0432 \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u043e\u043c \u043f\u0440\u043e\u043b\u0438\u0432\u0435\u000d\u000a\u0411\u0430\u0445\u0440\u0435\u0439\u043d \u043f\u0440\u0438 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0435 \u0434\u0440\u0443\u0433\u0438\u0445 \u0441\u0442\u0440\u0430\u043d \u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u0437\u0430\u043b\u0438\u0432\u0430 \u0440\u0430\u0437\u0440\u0430\u0431\u043e\u0442\u0430\u043b \u043f\u0440\u043e\u0435\u043a\u0442 \u0440\u0435\u0437\u043e\u043b\u044e\u0446\u0438\u0438, \u000d\u000a\u043f\u0440\u0438\u0437\u0432\u0430\u043d\u043d\u044b\u0439 \u0443\u0441\u0442\u0440\u0430\u043d\u0438\u0442\u044c \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u044f \u0441\u0443\u0434\u043e\u0445\u043e\u0434\u0441\u0442\u0432\u0430 \u0447\u0435\u0440\u0435\u0437 \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u0438\u0439 \u043f\u0440\u043e\u043b\u0438\u0432, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u0440\u0430\u043d\u0435\u0435 \u000d\u000a\u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0438\u0432\u0430\u043b \u043e\u043a\u043e\u043b\u043e 20% \u043c\u0438\u0440\u043e\u0432\u044b\u0445 \u043f\u043e\u0441\u0442\u0430\u0432\u043e\u043a \u043d\u0435\u0444\u0442\u0438 \u0438 \u0441\u0436\u0438\u0436\u0435\u043d\u043d\u043e\u0433\u043e \u043f\u0440\u0438\u0440\u043e\u0434\u043d\u043e\u0433\u043e \u0433\u0430\u0437\u0430.\u000d\u000a\u0420\u043e\u0441\u0441\u0438\u044f \u0438 \u041a\u0438\u0442\u0430\u0439 \u043d\u0430\u043b\u043e\u0436\u0438\u043b\u0438 \u0432\u0435\u0442\u043e \u043d\u0430 \u043f\u0440\u043e\u0435\u043a\u0442 \u000d\u000a\u0440\u0435\u0437\u043e\u043b\u044e\u0446\u0438\u0438 \u0421\u043e\u0432\u0435\u0442\u0430 \u0411\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e\u0441\u0442\u0438 \u041e\u041e\u041d, \u000d\u000a\u043f\u0440\u0438\u0437\u044b\u0432\u0430\u0432\u0448\u0438\u0439 \u043c\u0435\u0436\u0434\u0443\u043d\u0430\u0440\u043e\u0434\u043d\u043e\u0435 \u0441\u043e\u043e\u0431\u0449\u0435\u0441\u0442\u0432\u043e \u000d\u000a\u043a\u043e\u043e\u0440\u0434\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0443\u0441\u0438\u043b\u0438\u044f \u043f\u043e \u0437\u0430\u0449\u0438\u0442\u0435 \u000d\u000a\u043a\u043e\u043c\u043c\u0435\u0440\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u0441\u0443\u0434\u043e\u0445\u043e\u0434\u0441\u0442\u0432\u0430 \u0432 \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u043e\u043c \u000d\u000a\u043f\u0440\u043e\u043b\u0438\u0432\u0435. \u041f\u043e\u0434\u0433\u043e\u0442\u043e\u0432\u043b\u0435\u043d\u043d\u044b\u0439 \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u043e\u043c \u000d\u000a\u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u0430\u043b\u0438 11 \u0438\u0437 15 \u0447\u043b\u0435\u043d\u043e\u0432 \u0421\u043e\u0432\u0435\u0442\u0430 \u000d\u000a\u0411\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e\u0441\u0442\u0438.\u000a\u000d\u000a\u041f\u043e\u0441\u0442\u043f\u0440\u0435\u0434 \u0421\u0428\u0410 \u043f\u0440\u0438 \u041e\u041e\u041d \u041c\u0430\u0439\u043a \u0423\u043e\u043b\u0442\u0446 \u000d\u000a\u0440\u0430\u0441\u043a\u0440\u0438\u0442\u0438\u043a\u043e\u0432\u0430\u043b \u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u0420\u043e\u0441\u0441\u0438\u0438 \u0438 \u041a\u0438\u0442\u0430\u044f, \u000d\u000a\u0437\u0430\u044f\u0432\u0438\u0432, \u0447\u0442\u043e \u0418\u0440\u0430\u043d \u00ab\u0434\u0435\u0440\u0436\u0438\u0442 \u043c\u0438\u0440\u043e\u0432\u0443\u044e \u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0443 \u000d\u000a\u043f\u043e\u0434 \u043f\u0440\u0438\u0446\u0435\u043b\u043e\u043c\u00bb, \u043f\u0440\u0435\u043f\u044f\u0442\u0441\u0442\u0432\u0443\u044f \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0430\u043c \u000d\u000a\u0433\u0443\u043c\u0430\u043d\u0438\u0442\u0430\u0440\u043d\u043e\u0439 \u043f\u043e\u043c\u043e\u0449\u0438 \u0438 \u043a\u043e\u043c\u043c\u0435\u0440\u0447\u0435\u0441\u043a\u0438\u0445 \u0433\u0440\u0443\u0437\u043e\u0432. \u000d\u000a\u041e\u043d \u043f\u0440\u0438\u0437\u044b\u0432\u0430\u043b \u00ab\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0435 \u0441\u0442\u0440\u0430\u043d\u044b\u00bb \u000d\u000a\u043f\u0440\u0438\u0441\u043e\u0435\u0434\u0438\u043d\u0438\u0442\u044c\u0441\u044f \u043a \u0443\u0441\u0438\u043b\u0438\u044f\u043c \u043f\u043e \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0435\u043d\u0438\u044e \u000d\u000a\u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e\u0441\u0442\u0438 \u0432 \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u043e\u043c \u043f\u0440\u043e\u043b\u0438\u0432\u0435 \u000d\u000a\u0438 \u0441\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u0438\u044e \u0441\u0432\u043e\u0431\u043e\u0434\u044b \u0441\u0443\u0434\u043e\u0445\u043e\u0434\u0441\u0442\u0432\u0430.\u000a\u000d\u000a\u0420\u043e\u0441\u0441\u0438\u044f \u0438 \u041a\u0438\u0442\u0430\u0439 \u0432 \u0441\u0432\u043e\u044e \u043e\u0447\u0435\u0440\u0435\u0434\u044c \u0437\u0430\u044f\u0432\u0438\u043b\u0438, \u0447\u0442\u043e \u000d\u000a\u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u043d\u044b\u0439 \u0442\u0435\u043a\u0441\u0442 \u043d\u043e\u0441\u0438\u043b \u0430\u043d\u0442\u0438\u0438\u0440\u0430\u043d\u0441\u043a\u0438\u0439 \u000d\u000a\u0445\u0430\u0440\u0430\u043a\u0442\u0435\u0440. \u041f\u043e \u0441\u043b\u043e\u0432\u0430\u043c \u043f\u043e\u0441\u0442\u043f\u0440\u0435\u0434\u0430 \u041a\u0438\u0442\u0430\u044f \u0424\u0443 \u0426\u0443\u043d\u0430, \u000d\u000a\u043f\u0440\u0438\u043d\u044f\u0442\u0438\u0435 \u043f\u043e\u0434\u043e\u0431\u043d\u043e\u0439 \u0440\u0435\u0437\u043e\u043b\u044e\u0446\u0438\u0438 \u043f\u043e\u0441\u043b\u0430\u043b\u043e \u000d\u000a\u0431\u044b \u043d\u0435\u0432\u0435\u0440\u043d\u044b\u0439 \u0441\u0438\u0433\u043d\u0430\u043b \u043d\u0430 \u0444\u043e\u043d\u0435 \u043f\u0435\u0440\u0435\u0433\u043e\u0432\u043e\u0440\u043e\u0432 \u000d\u000a\u043e\u0431 \u0443\u0440\u0435\u0433\u0443\u043b\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0438 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u0430. \u0420\u043e\u0441\u0441\u0438\u0439\u0441\u043a\u0438\u0439 \u000d\u000a\u043f\u043e\u0441\u0442\u043f\u0440\u0435\u0434 \u0412\u0430\u0441\u0438\u043b\u0438\u0439 \u041d\u0435\u0431\u0435\u043d\u0437\u044f \u0441\u043e\u043e\u0431\u0449\u0438\u043b, \u0447\u0442\u043e \u000d\u000a\u041c\u043e\u0441\u043a\u0432\u0430 \u0438 \u041f\u0435\u043a\u0438\u043d \u0433\u043e\u0442\u043e\u0432\u044f\u0442 \u0430\u043b\u044c\u0442\u0435\u0440\u043d\u0430\u0442\u0438\u0432\u043d\u044b\u0439 \u000d\u000a\u043f\u0440\u043e\u0435\u043a\u0442 \u0440\u0435\u0437\u043e\u043b\u044e\u0446\u0438\u0438 \u043f\u043e \u0441\u0438\u0442\u0443\u0430\u0446\u0438\u0438 \u043d\u0430 \u0411\u043b\u0438\u0436\u043d\u0435\u043c \u000d\u000a\u0412\u043e\u0441\u0442\u043e\u043a\u0435.\u000a\u000d\u000a\u0418\u0437\u043d\u0430\u0447\u0430\u043b\u044c\u043d\u043e \u0431\u0430\u0445\u0440\u0435\u0439\u043d\u0441\u043a\u0438\u0439 \u043f\u0440\u043e\u0435\u043a\u0442 \u000d\u000a\u043f\u0440\u0435\u0434\u0443\u0441\u043c\u0430\u0442\u0440\u0438\u0432\u0430\u043b \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e\u0441\u0442\u044c \u043f\u0440\u0438\u043c\u0435\u043d\u0438\u0442\u044c \u0441\u0438\u043b\u0443 \u000d\u000a\u0434\u043b\u044f \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0435\u043d\u0438\u044f \u0441\u0432\u043e\u0431\u043e\u0434\u044b \u0441\u0443\u0434\u043e\u0445\u043e\u0434\u0441\u0442\u0432\u0430, \u043e\u0434\u043d\u0430\u043a\u043e \u000d\u000a\u043f\u043e\u0437\u0434\u043d\u0435\u0435 \u044d\u0442\u0438 \u043f\u043e\u043b\u043e\u0436\u0435\u043d\u0438\u044f \u0431\u044b\u043b\u0438 \u0438\u0441\u043a\u043b\u044e\u0447\u0435\u043d\u044b. \u000d\u000a\u0412 \u043e\u043a\u043e\u043d\u0447\u0430\u0442\u0435\u043b\u044c\u043d\u043e\u0439 \u0432\u0435\u0440\u0441\u0438\u0438 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0430 \u000d\u000a\u0441\u043e\u0434\u0435\u0440\u0436\u0430\u043b\u0441\u044f \u043b\u0438\u0448\u044c \u043f\u0440\u0438\u0437\u044b\u0432 \u043a \u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0430\u043c \u000d\u000a\u043a\u043e\u043e\u0440\u0434\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u043e\u0431\u043e\u0440\u043e\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u043c\u0435\u0440\u044b, \u000d\u000a\u0432\u043a\u043b\u044e\u0447\u0430\u044f \u0441\u043e\u043f\u0440\u043e\u0432\u043e\u0436\u0434\u0435\u043d\u0438\u0435 \u0442\u043e\u0440\u0433\u043e\u0432\u044b\u0445 \u0441\u0443\u0434\u043e\u0432 \u000d\u000a\u0438 \u043f\u0440\u0435\u0434\u043e\u0442\u0432\u0440\u0430\u0449\u0435\u043d\u0438\u0435 \u043f\u043e\u043f\u044b\u0442\u043e\u043a \u0431\u043b\u043e\u043a\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u000d\u000a\u041e\u0440\u043c\u0443\u0437\u0441\u043a\u0438\u0439 \u043f\u0440\u043e\u043b\u0438\u0432.\u000d\u000a02 09","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 3\u201310 \u0430\u043f\u0440\u0435\u043b\u044f 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b #\u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0430\u000d\u000a\u0421\u043d\u0438\u0436\u0435\u043d\u0438\u0435 \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u0430 \u0444\u043e\u0441\u0444\u0430\u0442\u043e\u0432 \u0443\u0432\u0435\u043b\u0438\u0447\u0438\u043b\u043e \u000d\u000a\u0442\u043e\u0440\u0433\u043e\u0432\u044b\u0439 \u0434\u0435\u0444\u0438\u0446\u0438\u0442 \u041c\u0430\u0440\u043e\u043a\u043a\u043e\u000d\u000a\u041c\u0430\u0440\u043e\u043a\u043a\u043e \u044f\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u043c \u0432 \u043c\u0438\u0440\u0435 \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u0435\u0440\u043e\u043c \u0444\u043e\u0441\u0444\u0430\u0442\u043e\u0432 \u0438 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0438\u0440\u0443\u0435\u0442 \u043e\u043a\u043e\u043b\u043e \u0434\u0432\u0443\u0445 \u000d\u000a\u0442\u0440\u0435\u0442\u0435\u0439 \u043c\u0438\u0440\u043e\u0432\u044b\u0445 \u0437\u0430\u043f\u0430\u0441\u043e\u0432 \u044d\u0442\u043e\u0433\u043e \u0441\u044b\u0440\u044c\u044f, \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u043c\u043e\u0433\u043e \u0432 \u0441\u0435\u043b\u044c\u0441\u043a\u043e\u043c \u0445\u043e\u0437\u044f\u0439\u0441\u0442\u0432\u0435 \u000d\u000a\u0438 \u043f\u0440\u043e\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u043e\u0441\u0442\u0438. \u041f\u0440\u043e\u0434\u0430\u0436\u0438 \u0444\u043e\u0441\u0444\u0430\u0442\u043e\u0432 \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0438\u0432\u0430\u044e\u0442 \u043e\u043a\u043e\u043b\u043e \u043f\u044f\u0442\u043e\u0439 \u0447\u0430\u0441\u0442\u0438 \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u043d\u044b\u0445 \u0434\u043e\u0445\u043e\u0434\u043e\u0432 \u000d\u000a\u0441\u0442\u0440\u0430\u043d\u044b.\u000d\u000a\u0422\u043e\u0440\u0433\u043e\u0432\u044b\u0439 \u0434\u0435\u0444\u0438\u0446\u0438\u0442 \u041c\u0430\u0440\u043e\u043a\u043a\u043e \u0432 \u044f\u043d\u0432\u0430\u0440\u0435\u0444\u0435\u0432\u0440\u0430\u043b\u0435 2026 \u0433\u043e\u0434\u0430 \u0443\u0432\u0435\u043b\u0438\u0447\u0438\u043b\u0441\u044f \u043d\u0430 \u0444\u043e\u043d\u0435 \u0440\u043e\u0441\u0442\u0430 \u000d\u000a\u0438\u043c\u043f\u043e\u0440\u0442\u0430 \u0438 \u0441\u043e\u043a\u0440\u0430\u0449\u0435\u043d\u0438\u044f \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u0430 \u0444\u043e\u0441\u0444\u0430\u0442\u043e\u0432, \u000d\u000a\u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u043e\u0441\u0442\u0430\u044e\u0442\u0441\u044f \u043e\u0434\u043d\u0438\u043c \u0438\u0437 \u043a\u043b\u044e\u0447\u0435\u0432\u044b\u0445 \u000d\u000a\u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u043e\u0432 \u0432\u0430\u043b\u044e\u0442\u043d\u043e\u0439 \u0432\u044b\u0440\u0443\u0447\u043a\u0438 \u0441\u0442\u0440\u0430\u043d\u044b.\u000a\u000d\u000a\u041f\u043e \u0434\u0430\u043d\u043d\u044b\u043c \u043c\u0430\u0440\u043e\u043a\u043a\u0430\u043d\u0441\u043a\u043e\u0433\u043e \u0443\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f \u000d\u000a\u043f\u043e \u0432\u0430\u043b\u044e\u0442\u043d\u044b\u043c \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u044f\u043c, \u0434\u0435\u0444\u0438\u0446\u0438\u0442 \u0432\u043d\u0435\u0448\u043d\u0435\u0439 \u000d\u000a\u0442\u043e\u0440\u0433\u043e\u0432\u043b\u0438 \u0437\u0430 \u043f\u0435\u0440\u0432\u044b\u0435 \u0434\u0432\u0430 \u043c\u0435\u0441\u044f\u0446\u0430 \u0433\u043e\u0434\u0430 \u0441\u043e\u0441\u0442\u0430\u0432\u0438\u043b \u000d\u000a\u043e\u043a\u043e\u043b\u043e 51,5 \u043c\u043b\u0440\u0434 \u0434\u0438\u0440\u0445\u0430\u043c\u043e\u0432 ($5,5 \u043c\u043b\u0440\u0434) \u043f\u0440\u043e\u0442\u0438\u0432 \u000d\u000a\u043f\u043e\u0447\u0442\u0438 50,5 \u043c\u043b\u0440\u0434 \u0434\u0438\u0440\u0445\u0430\u043c\u043e\u0432 ($5,39 \u043c\u043b\u0440\u0434) \u0433\u043e\u0434\u043e\u043c \u000d\u000a\u0440\u0430\u043d\u0435\u0435.\u000d\u000a\u0418\u043c\u043f\u043e\u0440\u0442 \u0432\u044b\u0440\u043e\u0441 \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u043d\u0430 1,8%, \u0434\u043e 126,5 \u043c\u043b\u0440\u0434 \u000d\u000a\u0434\u0438\u0440\u0445\u0430\u043c\u043e\u0432 ($13,5 \u043c\u043b\u0440\u0434), \u0442\u043e\u0433\u0434\u0430 \u043a\u0430\u043a \u043e\u0431\u0449\u0438\u0439 \u043e\u0431\u044a\u0435\u043c \u000d\u000a\u044d\u043a\u0441\u043f\u043e\u0440\u0442\u0430 \u0443\u0432\u0435\u043b\u0438\u0447\u0438\u043b\u0441\u044f \u043b\u0438\u0448\u044c \u043d\u0430 2% \u2014 \u0434\u043e 75 \u043c\u043b\u0440\u0434 \u000d\u000a\u0434\u0438\u0440\u0445\u0430\u043c\u043e\u0432 ($8,01 \u043c\u043b\u0440\u0434).\u000a\u000d\u000a\u041e\u0441\u043d\u043e\u0432\u043d\u044b\u043c \u0444\u0430\u043a\u0442\u043e\u0440\u043e\u043c \u0443\u0445\u0443\u0434\u0448\u0435\u043d\u0438\u044f \u0442\u043e\u0440\u0433\u043e\u0432\u043e\u0433\u043e \u000d\u000a\u0431\u0430\u043b\u0430\u043d\u0441\u0430 \u0441\u0442\u0430\u043b\u043e \u0441\u043d\u0438\u0436\u0435\u043d\u0438\u0435 \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u0430 \u0444\u043e\u0441\u0444\u0430\u0442\u043e\u0432 \u000d\u000a\u043d\u0430 16%. \u041f\u0440\u0438 \u044d\u0442\u043e\u043c \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0438 \u0430\u0432\u0442\u043e\u043c\u043e\u0431\u0438\u043b\u0435\u0439 \u000d\u000a\u0437\u0430 \u0440\u0443\u0431\u0435\u0436 \u0432\u044b\u0440\u043e\u0441\u043b\u0438 \u043f\u043e\u0447\u0442\u0438 \u043d\u0430 \u0442\u0430\u043a\u0443\u044e \u0436\u0435 \u0432\u0435\u043b\u0438\u0447\u0438\u043d\u0443, \u000d\u000a\u0447\u0430\u0441\u0442\u0438\u0447\u043d\u043e \u043a\u043e\u043c\u043f\u0435\u043d\u0441\u0438\u0440\u043e\u0432\u0430\u0432 \u0441\u043f\u0430\u0434 \u0432 \u0444\u043e\u0441\u0444\u0430\u0442\u043d\u043e\u043c \u000d\u000a\u0441\u0435\u043a\u0442\u043e\u0440\u0435.\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b #\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b\u000d\u000a\u041a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0438\u0439 \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u0435\u0432\u044b\u0439 \u0437\u0430\u0432\u043e\u0434 \u041e\u0410\u042d \u000d\u000a\u043e\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u043b \u0440\u0430\u0431\u043e\u0442\u0443 \u043f\u043e\u0441\u043b\u0435 \u0438\u0440\u0430\u043d\u0441\u043a\u043e\u0433\u043e \u0443\u0434\u0430\u0440\u0430\u000d\u000a\u0420\u0435\u0433\u0438\u043e\u043d \u0411\u043b\u0438\u0436\u043d\u0435\u0433\u043e \u0412\u043e\u0441\u0442\u043e\u043a\u0430 \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0438\u0432\u0430\u0435\u0442 \u043e\u043a\u043e\u043b\u043e 9% \u043c\u0438\u0440\u043e\u0432\u043e\u0433\u043e \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f \u2014 \u000d\u000a\u043a\u043b\u044e\u0447\u0435\u0432\u043e\u0433\u043e \u043c\u0435\u0442\u0430\u043b\u043b\u0430 \u0434\u043b\u044f \u0441\u0442\u0440\u043e\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430, \u0442\u0440\u0430\u043d\u0441\u043f\u043e\u0440\u0442\u0430 \u0438 \u0432\u043e\u0437\u043e\u0431\u043d\u043e\u0432\u043b\u044f\u0435\u043c\u043e\u0439 \u044d\u043d\u0435\u0440\u0433\u0435\u0442\u0438\u043a\u0438.\u000d\u000a\u0410\u043b\u044e\u043c\u0438\u043d\u0438\u0435\u0432\u044b\u0439 \u0437\u0430\u0432\u043e\u0434 Al Taweelah \u0432 \u0410\u0431\u0443-\u0414\u0430\u0431\u0438, \u000d\u000a\u043f\u0440\u0438\u043d\u0430\u0434\u043b\u0435\u0436\u0430\u0449\u0438\u0439 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 Emirates Global \u000d\u000aAluminium (EGA), \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u043b \u0440\u0430\u0431\u043e\u0442\u0443 \u000d\u000a\u0432 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0435 \u043d\u0435\u0434\u0430\u0432\u043d\u0435\u0433\u043e \u0438\u0440\u0430\u043d\u0441\u043a\u043e\u0433\u043e \u0443\u0434\u0430\u0440\u0430. \u000d\u000a\u041e\u0431 \u044d\u0442\u043e\u043c \u043a\u043e\u043d\u0441\u0430\u043b\u0442\u0438\u043d\u0433\u043e\u0432\u0430\u044f \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f Wood \u000d\u000aMackenzie \u0441\u043e\u043e\u0431\u0449\u0438\u043b\u0430 \u0432 \u0438\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044c\u0441\u043a\u043e\u0439 \u000d\u000a\u0437\u0430\u043f\u0438\u0441\u043a\u0435, \u043e\u043f\u0443\u0431\u043b\u0438\u043a\u043e\u0432\u0430\u043d\u043d\u043e\u0439 \u0437\u0430 \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0434\u043d\u0435\u0439 \u000d\u000a\u0434\u043e \u043f\u0435\u0440\u0435\u043c\u0438\u0440\u0438\u044f.\u000a\u000d\u000a\u0412 \u043f\u0440\u043e\u0448\u043b\u043e\u043c \u0433\u043e\u0434\u0443 \u0437\u0430\u0432\u043e\u0434 Al Taweelah \u0432\u044b\u043f\u0443\u0441\u0442\u0438\u043b \u000d\u000a1,6 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u044f. \u0420\u0430\u043d\u0435\u0435 EGA \u0441\u043e\u043e\u0431\u0449\u0430\u043b\u0430, \u000d\u000a\u0447\u0442\u043e \u043d\u0430 \u043c\u043e\u043c\u0435\u043d\u0442 \u043d\u0430\u0447\u0430\u043b\u0430 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u0430 \u0447\u0430\u0441\u0442\u044c \u000d\u000a\u0437\u0430\u043f\u0430\u0441\u043e\u0432 \u043c\u0435\u0442\u0430\u043b\u043b\u0430 \u043d\u0430\u0445\u043e\u0434\u0438\u043b\u0430\u0441\u044c \u0437\u0430 \u043f\u0440\u0435\u0434\u0435\u043b\u0430\u043c\u0438 \u000d\u000a\u041e\u0410\u042d, \u0447\u0442\u043e \u043f\u043e\u0437\u0432\u043e\u043b\u044f\u0435\u0442 \u0432\u044b\u043f\u043e\u043b\u043d\u0438\u0442\u044c \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430 \u000d\u000a\u043f\u0435\u0440\u0435\u0434 \u043a\u043b\u0438\u0435\u043d\u0442\u0430\u043c\u0438.\u000a\u000d\u000a\u041f\u043e \u0434\u0430\u043d\u043d\u044b\u043c Wood Mackenzie, \u0430\u043b\u044e\u043c\u0438\u043d\u0438\u0435\u0432\u044b\u0439 \u000d\u000a\u0437\u0430\u0432\u043e\u0434 \u0431\u0430\u0445\u0440\u0435\u0439\u043d\u0441\u043a\u043e\u0439 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 Aluminium Bahrain \u000d\u000a(Alba) \u0442\u0430\u043a\u0436\u0435 \u0437\u043d\u0430\u0447\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u043f\u043e\u0432\u0440\u0435\u0436\u0434\u0435\u043d \u0443\u0434\u0430\u0440\u043e\u043c \u000d\u000a\u0438, \u043a\u0430\u043a \u043e\u0436\u0438\u0434\u0430\u0435\u0442\u0441\u044f, \u0431\u0443\u0434\u0435\u0442 \u0440\u0430\u0431\u043e\u0442\u0430\u0442\u044c \u043b\u0438\u0448\u044c \u2028\u000d\u000a\u043d\u0430 30% \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0438.\u000a\u000d\u000a\u0420\u0430\u043d\u0435\u0435 EGA \u0438 Alba \u0441\u043e\u043e\u0431\u0449\u0438\u043b\u0438, \u0447\u0442\u043e \u043e\u0446\u0435\u043d\u0438\u0432\u0430\u044e\u0442 \u000d\u000a\u043c\u0430\u0441\u0448\u0442\u0430\u0431\u044b \u0443\u0449\u0435\u0440\u0431\u0430 \u0441\u0432\u043e\u0438\u043c \u043e\u0431\u044a\u0435\u043a\u0442\u0430\u043c, \u043d\u0435 \u0443\u0442\u043e\u0447\u043d\u044f\u044f, \u000d\u000a\u043a\u0430\u043a\u0438\u0435 \u0438\u043c\u0435\u043d\u043d\u043e \u044d\u043b\u0435\u043c\u0435\u043d\u0442\u044b \u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u044b \u0431\u044b\u043b\u0438 \u000d\u000a\u043f\u043e\u0432\u0440\u0435\u0436\u0434\u0435\u043d\u044b.\u000d\u000a03 09","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 3\u201310 \u0430\u043f\u0440\u0435\u043b\u044f 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u0430\u0432\u0438\u0430\u0446\u0438\u044f #\u043b\u043e\u0433\u0438\u0441\u0442\u0438\u043a\u0430 #\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b\u000d\u000aAirAsia \u043d\u0435 \u043e\u0442\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u043e\u0442 \u0437\u0430\u043f\u0443\u0441\u043a\u0430 \u0445\u0430\u0431\u0430 \u0432 \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0435, \u000d\u000a\u043d\u0435\u0441\u043c\u043e\u0442\u0440\u044f \u043d\u0430 \u0432\u043e\u0435\u043d\u043d\u044b\u0439 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u000d\u000a\u041a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u0435\u0449\u0435 \u0432 \u0444\u0435\u0432\u0440\u0430\u043b\u0435 \u043e\u0431\u044a\u044f\u0432\u0438\u043b\u0430 \u043e \u043f\u043b\u0430\u043d\u0430\u0445 \u0432\u043e\u0437\u043e\u0431\u043d\u043e\u0432\u0438\u0442\u044c \u0440\u0435\u0439\u0441\u044b \u0438\u0437 \u041a\u0443\u0430\u043b\u0430-\u041b\u0443\u043c\u043f\u0443\u0440\u0430 \u0432 \u041b\u043e\u043d\u0434\u043e\u043d \u000d\u000a\u0447\u0435\u0440\u0435\u0437 \u0411\u0430\u0445\u0440\u0435\u0439\u043d. \u0414\u043b\u044f \u0437\u0430\u043f\u0443\u0441\u043a\u0430 \u043c\u0430\u0440\u0448\u0440\u0443\u0442\u0430, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u0431\u044b\u043b \u043d\u0430\u043c\u0435\u0447\u0435\u043d \u043d\u0430 26 \u0438\u044e\u043d\u044f, \u043f\u0435\u0440\u0435\u0432\u043e\u0437\u0447\u0438\u043a \u043f\u0440\u0438\u043d\u044f\u043b \u000d\u000a\u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u0441\u043e\u0437\u0434\u0430\u0442\u044c \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u0430\u0432\u0438\u0430\u0446\u0438\u043e\u043d\u043d\u044b\u0439 \u0445\u0430\u0431 \u0432 \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0435 \u2014 \u043f\u0435\u0440\u0432\u044b\u0439 \u0437\u0430 \u043f\u0440\u0435\u0434\u0435\u043b\u0430\u043c\u0438 \u2028\u000d\u000a\u042e\u0433\u043e-\u0412\u043e\u0441\u0442\u043e\u0447\u043d\u043e\u0439 \u0410\u0437\u0438\u0438.\u000d\u000a\u041c\u0430\u043b\u0430\u0439\u0437\u0438\u0439\u0441\u043a\u0438\u0439 \u043b\u043e\u0443\u043a\u043e\u0441\u0442\u0435\u0440 AirAsia \u043f\u043e-\u043f\u0440\u0435\u0436\u043d\u0435\u043c\u0443 \u000d\u000a\u0440\u0430\u0441\u0441\u0447\u0438\u0442\u044b\u0432\u0430\u0435\u0442 \u043e\u0442\u043a\u0440\u044b\u0442\u044c \u0432 \u0438\u044e\u043d\u0435 \u043d\u043e\u0432\u044b\u0439 \u000d\u000a\u0430\u0432\u0438\u0430\u0446\u0438\u043e\u043d\u043d\u044b\u0439 \u0445\u0430\u0431 \u0432 \u0411\u0430\u0445\u0440\u0435\u0439\u043d\u0435, \u043d\u0435\u0441\u043c\u043e\u0442\u0440\u044f \u000d\u000a\u043d\u0430 \u0432\u043e\u0435\u043d\u043d\u044b\u0439 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442 \u043d\u0430 \u0411\u043b\u0438\u0436\u043d\u0435\u043c \u0412\u043e\u0441\u0442\u043e\u043a\u0435. \u000d\u000a\u041e\u0431 \u044d\u0442\u043e\u043c \u0437\u0430\u044f\u0432\u0438\u043b \u0433\u0435\u043d\u0435\u0440\u0430\u043b\u044c\u043d\u044b\u0439 \u0434\u0438\u0440\u0435\u043a\u0442\u043e\u0440 \u000d\u000a\u043f\u0435\u0440\u0435\u0432\u043e\u0437\u0447\u0438\u043a\u0430 \u0411\u043e \u041b\u0438\u043d\u0433\u0430\u043c.\u000a\u000d\u000aAirAsia \u043f\u043b\u0430\u043d\u0438\u0440\u0443\u0435\u0442 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u044c \u000d\u000a\u0443\u0437\u043a\u043e\u0444\u044e\u0437\u0435\u043b\u044f\u0436\u043d\u044b\u0435 \u0441\u0430\u043c\u043e\u043b\u0435\u0442\u044b \u0443\u0432\u0435\u043b\u0438\u0447\u0435\u043d\u043d\u043e\u0439 \u000d\u000a\u0434\u0430\u043b\u044c\u043d\u043e\u0441\u0442\u0438, \u043f\u0440\u0435\u0436\u0434\u0435 \u0432\u0441\u0435\u0433\u043e Airbus A321XLR, \u000d\u000a\u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u043f\u043e\u0437\u0432\u043e\u043b\u044f\u044e\u0442 \u0432\u044b\u043f\u043e\u043b\u043d\u044f\u0442\u044c \u000d\u000a\u043c\u0435\u0436\u043a\u043e\u043d\u0442\u0438\u043d\u0435\u043d\u0442\u0430\u043b\u044c\u043d\u044b\u0435 \u0440\u0435\u0439\u0441\u044b \u043f\u0440\u0438 \u0431\u043e\u043b\u0435\u0435 \u043d\u0438\u0437\u043a\u0438\u0445 \u000d\u000a\u0438\u0437\u0434\u0435\u0440\u0436\u043a\u0430\u0445.\u000d\u000a\u041f\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442 AirAsia \u0422\u043e\u043d\u0438 \u0424\u0435\u0440\u043d\u0430\u043d\u0434\u0435\u0441 \u0440\u0430\u043d\u0435\u0435 \u000d\u000a\u0437\u0430\u044f\u0432\u043b\u044f\u043b, \u0447\u0442\u043e \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u043d\u0430\u043c\u0435\u0440\u0435\u043d\u0430 \u0435\u0436\u0435\u0434\u043d\u0435\u0432\u043d\u043e \u000d\u000a\u0432\u044b\u043f\u043e\u043b\u043d\u044f\u0442\u044c \u0434\u043e 15 \u0440\u0435\u0439\u0441\u043e\u0432 \u0432 \u0411\u0430\u0445\u0440\u0435\u0439\u043d \u043d\u0430 \u0441\u0430\u043c\u043e\u043b\u0435\u0442\u0430\u0445 \u000d\u000aA321, \u0444\u043e\u0440\u043c\u0438\u0440\u0443\u044f \u0441\u0442\u044b\u043a\u043e\u0432\u043e\u0447\u043d\u044b\u0439 \u0443\u0437\u0435\u043b \u000d\u000a\u0441 \u043f\u043e\u0441\u043b\u0435\u0434\u0443\u044e\u0449\u0438\u043c \u043f\u043e\u0434\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u0435\u043c \u043a \u0435\u0432\u0440\u043e\u043f\u0435\u0439\u0441\u043a\u0438\u043c \u000d\u000a\u0438 \u0430\u0444\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u0438\u043c \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f\u043c.\u000a\u000d\u000a\u0412 \u043d\u0430\u0441\u0442\u043e\u044f\u0449\u0435\u0435 \u0432\u0440\u0435\u043c\u044f AirAsia \u0441\u0442\u0430\u043b\u043a\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u000d\u000a\u0441 \u0440\u043e\u0441\u0442\u043e\u043c \u0440\u0430\u0441\u0445\u043e\u0434\u043e\u0432 \u0438\u0437-\u0437\u0430 \u043f\u043e\u0434\u043e\u0440\u043e\u0436\u0430\u043d\u0438\u044f \u000d\u000a\u0430\u0432\u0438\u0430\u0446\u0438\u043e\u043d\u043d\u043e\u0433\u043e \u0442\u043e\u043f\u043b\u0438\u0432\u0430. \u041f\u043e\u0441\u043b\u0435 \u043d\u0430\u0447\u0430\u043b\u0430 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u0430 \u000d\u000a\u0446\u0435\u043d\u044b \u043d\u0430 \u043a\u0435\u0440\u043e\u0441\u0438\u043d \u0432 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u044b\u0445 \u0441\u0442\u0440\u0430\u043d\u0430\u0445 \u0434\u043e\u0441\u0442\u0438\u0433\u0430\u043b\u0438 \u000d\u000a$300 \u0437\u0430 \u0431\u0430\u0440\u0440\u0435\u043b\u044c.\u000d\u000a#\u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0430 #\u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0430\u000d\u000a\u041c\u0430\u0440\u043e\u043a\u043a\u043e \u0432\u043b\u043e\u0436\u0438\u0442 \u0435\u0449\u0435 $850 \u043c\u043b\u043d \u0432 \u0442\u0440\u0430\u043d\u0441\u043f\u043e\u0440\u0442\u043d\u0443\u044e \u000d\u000a\u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0443 \u043a \u0427\u041c-2030\u000d\u000a\u0412 \u043f\u0440\u043e\u0448\u043b\u043e\u043c \u0433\u043e\u0434\u0443 \u0432\u043b\u0430\u0441\u0442\u0438 \u0443\u0436\u0435 \u043e\u0434\u043e\u0431\u0440\u0438\u043b\u0438 148 \u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u043d\u044b\u0445 \u043f\u0440\u043e\u0435\u043a\u0442\u043e\u0432 \u2028\u000d\u000a\u043d\u0430 \u0441\u0443\u043c\u043c\u0443 \u043e\u043a\u043e\u043b\u043e $4 \u043c\u043b\u0440\u0434.\u000d\u000a\u041c\u0430\u0440\u043e\u043a\u043a\u043e \u043f\u043b\u0430\u043d\u0438\u0440\u0443\u0435\u0442 \u0432\u043b\u043e\u0436\u0438\u0442\u044c 8 \u043c\u043b\u0440\u0434 \u0434\u0438\u0440\u0445\u0430\u043c\u043e\u0432 \u000d\u000a($850 \u043c\u043b\u043d) \u0432 \u0442\u0440\u0430\u043d\u0441\u043f\u043e\u0440\u0442\u043d\u0443\u044e \u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0443 \u000d\u000a\u0432 \u0440\u0430\u043c\u043a\u0430\u0445 \u043f\u043e\u0434\u0433\u043e\u0442\u043e\u0432\u043a\u0438 \u043a \u043f\u0440\u043e\u0432\u0435\u0434\u0435\u043d\u0438\u044e \u000d\u000a\u0447\u0435\u043c\u043f\u0438\u043e\u043d\u0430\u0442\u0430 \u043c\u0438\u0440\u0430 \u043f\u043e \u0444\u0443\u0442\u0431\u043e\u043b\u0443 2030 \u0433\u043e\u0434\u0430, \u000d\u000a\u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u0441\u0442\u0440\u0430\u043d\u0430 \u043f\u0440\u0438\u043c\u0435\u0442 \u0441\u043e\u0432\u043c\u0435\u0441\u0442\u043d\u043e \u0441 \u0418\u0441\u043f\u0430\u043d\u0438\u0435\u0439 \u000d\u000a\u0438 \u041f\u043e\u0440\u0442\u0443\u0433\u0430\u043b\u0438\u0435\u0439.\u000a\u000d\u000a\u041a\u0430\u043a \u0441\u043e\u043e\u0431\u0449\u0438\u043b \u043c\u0438\u043d\u0438\u0441\u0442\u0440 \u0442\u0440\u0430\u043d\u0441\u043f\u043e\u0440\u0442\u0430 \u0438 \u043b\u043e\u0433\u0438\u0441\u0442\u0438\u043a\u0438 \u000d\u000a\u041c\u0430\u0440\u043e\u043a\u043a\u043e \u0410\u0431\u0434\u0435\u043b\u044c \u0421\u0430\u043c\u0430\u0434 \u041a\u0430\u0439\u044e, \u0432 \u044d\u0442\u043e\u043c \u0433\u043e\u0434\u0443 \u000d\u000a\u0432\u043b\u0430\u0441\u0442\u0438 \u0440\u0430\u0441\u0441\u0447\u0438\u0442\u044b\u0432\u0430\u044e\u0442 \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u044c 151 \u043d\u043e\u0432\u044b\u0439\u000d\u000a\u043f\u0440\u043e\u0435\u043a\u0442, \u0431\u043e\u043b\u044c\u0448\u0430\u044f \u0447\u0430\u0441\u0442\u044c \u043a\u043e\u0442\u043e\u0440\u044b\u0445 \u0431\u0443\u0434\u0435\u0442 \u0441\u0432\u044f\u0437\u0430\u043d\u0430 \u000d\u000a\u0441 \u0436\u0435\u043b\u0435\u0437\u043d\u043e\u0434\u043e\u0440\u043e\u0436\u043d\u043e\u0439 \u0438\u043d\u0444\u0440\u0430\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u043e\u0439.\u000a\u000d\u000a\u041f\u043e \u0441\u043b\u043e\u0432\u0430\u043c \u043c\u0438\u043d\u0438\u0441\u0442\u0440\u0430, \u043e\u0434\u043d\u0438\u043c \u0438\u0437 \u043a\u043b\u044e\u0447\u0435\u0432\u044b\u0445 \u000d\u000a\u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0439 \u0441\u0442\u0430\u043d\u0435\u0442 \u0441\u0442\u0440\u043e\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u000d\u000a\u0432\u044b\u0441\u043e\u043a\u043e\u0441\u043a\u043e\u0440\u043e\u0441\u0442\u043d\u043e\u0439 \u0436\u0435\u043b\u0435\u0437\u043d\u043e\u0434\u043e\u0440\u043e\u0436\u043d\u043e\u0439 \u043b\u0438\u043d\u0438\u0438, \u000d\u000a\u043a\u043e\u0442\u043e\u0440\u0430\u044f \u0441\u043e\u0435\u0434\u0438\u043d\u0438\u0442 \u043e\u0441\u043d\u043e\u0432\u043d\u044b\u0435 \u0433\u043e\u0440\u043e\u0434\u0430 \u0441\u0435\u0432\u0435\u0440\u043e\u0437\u0430\u043f\u0430\u0434\u0430 \u041c\u0430\u0440\u043e\u043a\u043a\u043e.\u000d\u000a04 09","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 3\u201310 \u0430\u043f\u0440\u0435\u043b\u044f 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u043b\u043e\u0433\u0438\u0441\u0442\u0438\u043a\u0430 #\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b\u000d\u000aVale \u0434\u043e\u0441\u0440\u043e\u0447\u043d\u043e \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442 \u0437\u0430\u0432\u043e\u0434\u044b \u0432 \u041e\u043c\u0430\u043d\u0435 \u2028\u000d\u000a\u043d\u0430 \u0444\u043e\u043d\u0435 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u0430 \u043d\u0430 \u0411\u043b\u0438\u0436\u043d\u0435\u043c \u0412\u043e\u0441\u0442\u043e\u043a\u0435\u000d\u000a\u041c\u043e\u0449\u043d\u043e\u0441\u0442\u0438 \u043e\u043c\u0430\u043d\u0441\u043a\u0438\u0445 \u0430\u043a\u0442\u0438\u0432\u043e\u0432 Vale \u0441\u043e\u0441\u0442\u0430\u0432\u043b\u044f\u044e\u0442 9 \u043c\u043b\u043d \u0442\u043e\u043d\u043d \u0436\u0435\u043b\u0435\u0437\u043e\u0440\u0443\u0434\u043d\u044b\u0445 \u043e\u043a\u0430\u0442\u044b\u0448\u0435\u0439 \u0432 \u0433\u043e\u0434. \u000d\u000a\u042d\u0442\u043e \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e 29% \u043e\u0431\u0449\u0435\u0433\u043e \u043e\u0431\u044a\u0435\u043c\u0430 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u0432 \u043f\u0440\u043e\u0448\u043b\u043e\u043c \u0433\u043e\u0434\u0443.\u000d\u000a\u0411\u0440\u0430\u0437\u0438\u043b\u044c\u0441\u043a\u0430\u044f \u0433\u043e\u0440\u043d\u043e\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0430\u044f \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u000d\u000aVale \u0434\u043e\u0441\u0440\u043e\u0447\u043d\u043e \u043f\u0440\u043e\u0432\u0435\u0434\u0435\u0442 \u043f\u043b\u0430\u043d\u043e\u0432\u0443\u044e \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0443 \u000d\u000a\u0434\u0432\u0443\u0445 \u0437\u0430\u0432\u043e\u0434\u043e\u0432 \u043f\u043e \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0443 \u0436\u0435\u043b\u0435\u0437\u043e\u0440\u0443\u0434\u043d\u044b\u0445 \u000d\u000a\u043e\u043a\u0430\u0442\u044b\u0448\u0435\u0439 \u0432 \u041e\u043c\u0430\u043d\u0435 \u043d\u0430 \u0444\u043e\u043d\u0435 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u0430 \u000d\u000a\u043d\u0430 \u0411\u043b\u0438\u0436\u043d\u0435\u043c \u0412\u043e\u0441\u0442\u043e\u043a\u0435. \u041e\u0431 \u044d\u0442\u043e\u043c \u0441\u043e\u043e\u0431\u0449\u0438\u043b\u043e \u000d\u000a\u0430\u0433\u0435\u043d\u0442\u0441\u0442\u0432\u043e Bloomberg \u0441\u043e \u0441\u0441\u044b\u043b\u043a\u043e\u0439 \u043d\u0430 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0438.\u000a\u000d\u000a\u041f\u043e \u0441\u043b\u043e\u0432\u0430\u043c \u0441\u043e\u0431\u0435\u0441\u0435\u0434\u043d\u0438\u043a\u043e\u0432 \u0430\u0433\u0435\u043d\u0442\u0441\u0442\u0432\u0430, \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u000d\u000a\u043f\u0435\u0440\u0435\u043d\u0435\u0441\u043b\u0430 \u0437\u0430\u043f\u043b\u0430\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u043d\u0430 \u043f\u0435\u0440\u0432\u043e\u0435 \u000d\u000a\u043f\u043e\u043b\u0443\u0433\u043e\u0434\u0438\u0435 \u043f\u0440\u043e\u0444\u0438\u043b\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u0440\u0430\u0431\u043e\u0442\u044b \u000d\u000a\u043d\u0430 \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u043d\u0435\u0434\u0435\u043b\u044c \u0432\u043f\u0435\u0440\u0435\u0434, \u0447\u0442\u043e\u0431\u044b \u0441\u043d\u0438\u0437\u0438\u0442\u044c \u000d\u000a\u0438\u0437\u0434\u0435\u0440\u0436\u043a\u0438, \u0432\u043e\u0437\u043d\u0438\u043a\u0448\u0438\u0435 \u0432 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0435 \u0431\u043b\u043e\u043a\u0430\u0434\u044b \u000d\u000a\u041e\u0440\u043c\u0443\u0437\u0441\u043a\u043e\u0433\u043e \u043f\u0440\u043e\u043b\u0438\u0432\u0430. \u0421\u0440\u043e\u043a\u0438 \u043f\u0440\u043e\u0441\u0442\u043e\u044f \u000d\u000a\u043f\u0440\u0435\u0434\u043f\u0440\u0438\u044f\u0442\u0438\u0439 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a \u043d\u0435 \u0443\u0442\u043e\u0447\u043d\u0438\u043b.\u000d\u000aVale \u043e\u0442\u0433\u0440\u0443\u0436\u0430\u0435\u0442 \u043f\u0440\u043e\u0434\u0443\u043a\u0446\u0438\u044e \u043a\u043b\u0438\u0435\u043d\u0442\u0430\u043c \u0432 \u0441\u0442\u0440\u0430\u043d\u0430\u0445 \u000d\u000a\u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u0437\u0430\u043b\u0438\u0432\u0430, \u0432\u043a\u043b\u044e\u0447\u0430\u044f \u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0443\u044e \u000d\u000a\u0410\u0440\u0430\u0432\u0438\u044e, \u041e\u0431\u044a\u0435\u0434\u0438\u043d\u0435\u043d\u043d\u044b\u0435 \u0410\u0440\u0430\u0431\u0441\u043a\u0438\u0435 \u042d\u043c\u0438\u0440\u0430\u0442\u044b \u000d\u000a\u0438 \u041a\u0430\u0442\u0430\u0440. \u041e\u0434\u043d\u0430\u043a\u043e \u0431\u043b\u043e\u043a\u0430\u0434\u0430 \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u043e\u0433\u043e \u043f\u0440\u043e\u043b\u0438\u0432\u0430 \u000d\u000a\u0441\u043e \u0441\u0442\u043e\u0440\u043e\u043d\u044b \u0418\u0440\u0430\u043d\u0430 \u0444\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u043b\u0430 \u000d\u000a\u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0438 \u0432 \u0440\u0435\u0433\u0438\u043e\u043d.\u000a\u000d\u000a\u041f\u043e \u0441\u043b\u043e\u0432\u0430\u043c \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u0430, \u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u043f\u0435\u0440\u0435\u043d\u0435\u0441\u0442\u0438 \u043f\u0430\u0443\u0437\u0443 \u000d\u000a\u0432 \u0440\u0430\u0431\u043e\u0442\u0435 \u0437\u0430\u0432\u043e\u0434\u043e\u0432 \u0442\u0430\u043a\u0436\u0435 \u043e\u0431\u044a\u044f\u0441\u043d\u044f\u0435\u0442, \u043f\u043e\u0447\u0435\u043c\u0443 \u0441\u0443\u0434\u0430 \u000d\u000a\u0441 \u0436\u0435\u043b\u0435\u0437\u043d\u043e\u0439 \u0440\u0443\u0434\u043e\u0439 Vale \u0438\u0437 \u0411\u0440\u0430\u0437\u0438\u043b\u0438\u0438 \u043d\u0430\u0447\u0430\u043b\u0438 \u000d\u000a\u043f\u0435\u0440\u0435\u043d\u0430\u043f\u0440\u0430\u0432\u043b\u044f\u0442\u044c \u0432 \u0434\u0440\u0443\u0433\u0438\u0435 \u0440\u0435\u0433\u0438\u043e\u043d\u044b \u0432\u043c\u0435\u0441\u0442\u043e \u000d\u000a\u0411\u043b\u0438\u0436\u043d\u0435\u0433\u043e \u0412\u043e\u0441\u0442\u043e\u043a\u0430.\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b #\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b\u000d\u000a\u0421\u0443\u0434\u0430\u043d \u0441\u043e\u043a\u0440\u0430\u0442\u0438\u043b \u044d\u043a\u0441\u043f\u043e\u0440\u0442 \u0437\u043e\u043b\u043e\u0442\u0430 \u0432 \u041e\u0410\u042d \u043f\u043e\u0441\u043b\u0435 \u000d\u000a\u0440\u0430\u0437\u0440\u044b\u0432\u0430 \u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u0439 \u043c\u0435\u0436\u0434\u0443 \u0441\u0442\u0440\u0430\u043d\u0430\u043c\u0438\u000d\u000a\u0421 \u0430\u043f\u0440\u0435\u043b\u044f 2024 \u0433\u043e\u0434\u0430 \u0432 \u0421\u0443\u0434\u0430\u043d\u0435 \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0430\u0435\u0442\u0441\u044f \u0432\u043e\u043e\u0440\u0443\u0436\u0435\u043d\u043d\u044b\u0439 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442 \u043c\u0435\u0436\u0434\u0443 \u0430\u0440\u043c\u0438\u0435\u0439 \u0441\u0442\u0440\u0430\u043d\u044b \u000d\u000a\u0438 \u0442\u0430\u043a \u043d\u0430\u0437\u044b\u0432\u0430\u0435\u043c\u044b\u043c\u0438 \u0441\u0438\u043b\u0430\u043c\u0438 \u0431\u044b\u0441\u0442\u0440\u043e\u0433\u043e \u0440\u0435\u0430\u0433\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f, \u043a\u043e\u0442\u043e\u0440\u044b\u043c \u041e\u0410\u042d \u043e\u043a\u0430\u0437\u044b\u0432\u0430\u044e\u0442 \u0444\u0438\u043d\u0430\u043d\u0441\u043e\u0432\u0443\u044e \u000d\u000a\u0438 \u0432\u043e\u0435\u043d\u043d\u0443\u044e \u043f\u043e\u043c\u043e\u0449\u044c. \u0412\u043b\u0430\u0441\u0442\u0438 \u0421\u0443\u0434\u0430\u043d\u0430 \u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u043e \u0440\u0430\u0437\u043e\u0440\u0432\u0430\u043b\u0438 \u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u044f \u0441 \u041e\u0410\u042d \u0432 \u043c\u0430\u0435 \u043f\u0440\u043e\u0448\u043b\u043e\u0433\u043e \u000d\u000a\u0433\u043e\u0434\u0430.\u000d\u000a\u042d\u043a\u0441\u043f\u043e\u0440\u0442 \u0437\u043e\u043b\u043e\u0442\u0430 \u0438\u0437 \u0421\u0443\u0434\u0430\u043d\u0430 \u0432 \u041e\u0410\u042d \u0440\u0435\u0437\u043a\u043e \u000d\u000a\u0441\u043e\u043a\u0440\u0430\u0442\u0438\u043b\u0441\u044f \u0432 2025 \u0433\u043e\u0434\u0443 \u043f\u043e\u0441\u043b\u0435 \u0440\u0430\u0437\u0440\u044b\u0432\u0430 \u000d\u000a\u0434\u0438\u043f\u043b\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u0439 \u043c\u0435\u0436\u0434\u0443 \u0441\u0442\u0440\u0430\u043d\u0430\u043c\u0438, \u000d\u000a\u0441\u043e\u043e\u0431\u0449\u0430\u0435\u0442 Bloomberg.\u000a\u000d\u000a\u041f\u043e \u0434\u0430\u043d\u043d\u044b\u043c \u0430\u0433\u0435\u043d\u0442\u0441\u0442\u0432\u0430, \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0438 \u0437\u043e\u043b\u043e\u0442\u0430 \u0432 \u041e\u0410\u042d \u000d\u000a\u0441\u043e\u0441\u0442\u0430\u0432\u0438\u043b\u0438 \u043e\u043a\u043e\u043b\u043e 8,2 \u0442\u043e\u043d\u043d\u044b \u043f\u0440\u043e\u0442\u0438\u0432 22,2 \u0442\u043e\u043d\u043d\u044b \u000d\u000a\u0433\u043e\u0434\u043e\u043c \u0440\u0430\u043d\u0435\u0435. \u0414\u043e\u043b\u044f \u041e\u0410\u042d \u0432 \u043e\u0431\u0449\u0435\u043c \u043e\u0431\u044a\u0435\u043c\u0435 \u000d\u000a\u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u0430 \u0441\u0443\u0434\u0430\u043d\u0441\u043a\u043e\u0433\u043e \u0437\u043e\u043b\u043e\u0442\u0430 \u000d\u000a\u0441\u043d\u0438\u0437\u0438\u043b\u0430\u0441\u044c \u0441 99% \u0434\u043e 56%. \u0421\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u044c \u043f\u043e\u0441\u0442\u0430\u0432\u043e\u043a \u000d\u000a\u0441\u043e\u043a\u0440\u0430\u0442\u0438\u043b\u0430\u0441\u044c \u0441 $1,5 \u043c\u043b\u0440\u0434 \u0434\u043e $865 \u043c\u043b\u043d.\u000a\u000d\u000a\u0427\u0430\u0441\u0442\u044c \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u0430 \u0431\u044b\u043b\u0430 \u043f\u0435\u0440\u0435\u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0430 \u0432 \u0434\u0440\u0443\u0433\u0438\u0435 \u000d\u000a\u0441\u0442\u0440\u0430\u043d\u044b \u0440\u0435\u0433\u0438\u043e\u043d\u0430. \u0415\u0433\u0438\u043f\u0435\u0442 \u0432 2025 \u0433\u043e\u0434\u0443 \u000d\u000a\u0438\u043c\u043f\u043e\u0440\u0442\u0438\u0440\u043e\u0432\u0430\u043b 4,9 \u0442\u043e\u043d\u043d\u044b \u0441\u0443\u0434\u0430\u043d\u0441\u043a\u043e\u0433\u043e \u0437\u043e\u043b\u043e\u0442\u0430 \u000d\u000a\u043d\u0430 \u0441\u0443\u043c\u043c\u0443 $517 \u043c\u043b\u043d, \u0447\u0442\u043e \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u0432 20 \u0440\u0430\u0437 \u000d\u000a\u0431\u043e\u043b\u044c\u0448\u0435, \u0447\u0435\u043c \u0433\u043e\u0434\u043e\u043c \u0440\u0430\u043d\u0435\u0435.\u000a\u000d\u000a\u041f\u043e\u0441\u0442\u0430\u0432\u043a\u0438 \u0432 \u041e\u043c\u0430\u043d \u0443\u0434\u0432\u043e\u0438\u043b\u0438\u0441\u044c \u0438 \u0434\u043e\u0441\u0442\u0438\u0433\u043b\u0438 0,7 \u0442\u043e\u043d\u043d\u044b \u000d\u000a\u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u044c\u044e $77 \u043c\u043b\u043d. \u041a\u0430\u0442\u0430\u0440 \u0437\u0430\u043a\u0443\u043f\u0438\u043b 382 \u043a\u0433 \u000d\u000a\u0437\u043e\u043b\u043e\u0442\u0430 \u043d\u0430 $41 \u043c\u043b\u043d. \u042d\u0444\u0438\u043e\u043f\u0438\u044f, \u0440\u0430\u043d\u0435\u0435 \u000d\u000a\u043d\u0435 \u0438\u043c\u043f\u043e\u0440\u0442\u0438\u0440\u043e\u0432\u0430\u0432\u0448\u0430\u044f \u0441\u0443\u0434\u0430\u043d\u0441\u043a\u043e\u0435 \u0437\u043e\u043b\u043e\u0442\u043e, \u000d\u000a\u043f\u043e\u043b\u0443\u0447\u0438\u043b\u0430 294 \u043a\u0438\u043b\u043e\u0433\u0440\u0430\u043c\u043c\u0430 \u043d\u0430 $31 \u043c\u043b\u043d.\u000a\u000d\u000a\u0412\u0441\u0435\u0433\u043e \u0432 2025 \u0433\u043e\u0434\u0443 \u0421\u0443\u0434\u0430\u043d \u043e\u0444\u0438\u0446\u0438\u0430\u043b\u044c\u043d\u043e \u000d\u000a\u044d\u043a\u0441\u043f\u043e\u0440\u0442\u0438\u0440\u043e\u0432\u0430\u043b 14,7 \u0442\u043e\u043d\u043d\u044b \u0437\u043e\u043b\u043e\u0442\u0430 \u043f\u0440\u043e\u0442\u0438\u0432 \u000d\u000a22,9 \u0442\u043e\u043d\u043d\u044b \u0433\u043e\u0434\u043e\u043c \u0440\u0430\u043d\u0435\u0435. \u041f\u0440\u0438 \u044d\u0442\u043e\u043c \u0434\u043e\u0445\u043e\u0434\u044b \u000d\u000a\u043e\u0442 \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u0430 \u043e\u0441\u0442\u0430\u043b\u0438\u0441\u044c \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u043d\u0430 \u0441\u043e\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u043c\u043e\u043c \u000d\u000a\u0443\u0440\u043e\u0432\u043d\u0435 \u0431\u043b\u0430\u0433\u043e\u0434\u0430\u0440\u044f \u0440\u043e\u0441\u0442\u0443 \u043c\u0438\u0440\u043e\u0432\u044b\u0445 \u0446\u0435\u043d \u043d\u0430 \u0437\u043e\u043b\u043e\u0442\u043e.\u000d\u000a05 09","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 3\u201310 \u0430\u043f\u0440\u0435\u043b\u044f 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u0432\u043e\u043e\u0440\u0443\u0436\u0435\u043d\u0438\u044f #\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b\u000d\u000a\u0421\u0442\u0440\u0430\u043d\u044b \u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u0437\u0430\u043b\u0438\u0432\u0430 \u0437\u0430\u0438\u043d\u0442\u0435\u0440\u0435\u0441\u043e\u0432\u0430\u043b\u0438\u0441\u044c \u000d\u000a\u0434\u0435\u0448\u0435\u0432\u044b\u043c\u0438 \u0443\u043a\u0440\u0430\u0438\u043d\u0441\u043a\u0438\u043c\u0438 \u0434\u0440\u043e\u043d\u0430\u043c\u0438 \u0434\u043b\u044f \u0437\u0430\u0449\u0438\u0442\u044b \u000d\u000a\u043e\u0442 \u0438\u0440\u0430\u043d\u0441\u043a\u0438\u0445 \u0430\u0442\u0430\u043a\u000d\u000a\u041a \u043c\u043e\u043c\u0435\u043d\u0442\u0443 \u043f\u0440\u0435\u043a\u0440\u0430\u0449\u0435\u043d\u0438\u044f \u043e\u0433\u043d\u044f, \u043a\u043e\u0442\u043e\u0440\u043e\u0435 \u0431\u044b\u043b\u043e \u043e\u0431\u044a\u044f\u0432\u043b\u0435\u043d\u043e 8 \u0430\u043f\u0440\u0435\u043b\u044f, \u0418\u0440\u0430\u043d \u0437\u0430\u043f\u0443\u0441\u0442\u0438\u043b \u043f\u043e \u0441\u0442\u0440\u0430\u043d\u0430\u043c \u000d\u000a\u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u0437\u0430\u043b\u0438\u0432\u0430 \u0431\u043e\u043b\u0435\u0435 3,5 \u0442\u044b\u0441. \u0431\u0435\u0441\u043f\u0438\u043b\u043e\u0442\u043d\u0438\u043a\u043e\u0432. \u0418\u0437 \u043d\u0438\u0445 2256 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043b\u0438\u0441\u044c \u0434\u043b\u044f \u0430\u0442\u0430\u043a \u000d\u000a\u043d\u0430 \u0442\u0435\u0440\u0440\u0438\u0442\u043e\u0440\u0438\u044e \u041e\u0431\u044a\u0435\u0434\u0438\u043d\u0435\u043d\u043d\u044b\u0445 \u0410\u0440\u0430\u0431\u0441\u043a\u0438\u0445 \u042d\u043c\u0438\u0440\u0430\u0442\u043e\u0432.\u000d\u000a\u0421\u0442\u0440\u0430\u043d\u044b \u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u0437\u0430\u043b\u0438\u0432\u0430, \u0432\u043a\u043b\u044e\u0447\u0430\u044f \u000d\u000a\u0421\u0430\u0443\u0434\u043e\u0432\u0441\u043a\u0443\u044e \u0410\u0440\u0430\u0432\u0438\u044e \u0438 \u041e\u0410\u042d, \u0438\u0437\u0443\u0447\u0430\u044e\u0442 \u000d\u000a\u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e\u0441\u0442\u044c \u0437\u0430\u043a\u0443\u043f\u043a\u0438 \u0434\u0435\u0448\u0435\u0432\u044b\u0445 \u0434\u0440\u043e\u043d\u043e\u0432\u043f\u0435\u0440\u0435\u0445\u0432\u0430\u0442\u0447\u0438\u043a\u043e\u0432 \u0443\u043a\u0440\u0430\u0438\u043d\u0441\u043a\u043e\u0433\u043e \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0430 \u000d\u000a\u0434\u043b\u044f \u043e\u0442\u0440\u0430\u0436\u0435\u043d\u0438\u044f \u0438\u0440\u0430\u043d\u0441\u043a\u0438\u0445 \u0430\u0442\u0430\u043a, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u0431\u044b\u0441\u0442\u0440\u043e \u000d\u000a\u0438\u0441\u0442\u043e\u0449\u0430\u044e\u0442 \u0437\u0430\u043f\u0430\u0441\u044b \u0434\u043e\u0440\u043e\u0433\u043e\u0441\u0442\u043e\u044f\u0449\u0438\u0445 \u000d\u000a\u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u0438\u0445 \u0440\u0430\u043a\u0435\u0442 \u0434\u043b\u044f \u0441\u0438\u0441\u0442\u0435\u043c \u000d\u000a\u043f\u0440\u043e\u0442\u0438\u0432\u043e\u0432\u043e\u0437\u0434\u0443\u0448\u043d\u043e\u0439 \u043e\u0431\u043e\u0440\u043e\u043d\u044b.\u000a\u000d\u000a\u041a\u0430\u043a \u0441\u043e\u043e\u0431\u0449\u0438\u043b \u0430\u0433\u0435\u043d\u0442\u0441\u0442\u0432\u0443 Reuters \u044f\u043f\u043e\u043d\u0441\u043a\u0438\u0439 \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044c \u0431\u0435\u0441\u043f\u0438\u043b\u043e\u0442\u043d\u0438\u043a\u043e\u0432 Terra Drone, \u000d\u000a\u0440\u0435\u0447\u044c \u0438\u0434\u0435\u0442 \u043e \u043f\u0435\u0440\u0435\u0445\u0432\u0430\u0442\u0447\u0438\u043a\u0435 Terra A1 \u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u044c\u044e \u000d\u000a$2,5 \u0442\u044b\u0441., \u0440\u0430\u0437\u0440\u0430\u0431\u043e\u0442\u0430\u043d\u043d\u043e\u043c \u0441\u043e\u0432\u043c\u0435\u0441\u0442\u043d\u043e \u000d\u000a\u0441 \u0443\u043a\u0440\u0430\u0438\u043d\u0441\u043a\u0438\u043c \u0441\u0442\u0430\u0440\u0442\u0430\u043f\u043e\u043c Amazing Drones. \u000d\u000a\u041f\u043e \u0441\u043b\u043e\u0432\u0430\u043c \u0433\u043b\u0430\u0432\u044b \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u0422\u043e\u0440\u0443 \u0422\u043e\u043a\u0443\u0441\u0438\u0433\u044d, \u043f\u043e\u0441\u043b\u0435 \u000d\u000a\u043d\u0430\u0447\u0430\u043b\u0430 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u0430 \u0447\u0438\u0441\u043b\u043e \u0437\u0430\u043f\u0440\u043e\u0441\u043e\u0432 \u0438\u0437 \u0441\u0442\u0440\u0430\u043d \u000d\u000a\u0411\u043b\u0438\u0436\u043d\u0435\u0433\u043e \u0412\u043e\u0441\u0442\u043e\u043a\u0430 \u0440\u0435\u0437\u043a\u043e \u0432\u044b\u0440\u043e\u0441\u043b\u043e.\u000a\u000d\u000a\u0418\u0440\u0430\u043d \u043c\u0430\u0441\u0441\u043e\u0432\u043e \u043f\u0440\u0438\u043c\u0435\u043d\u044f\u043b \u0434\u0435\u0448\u0435\u0432\u044b\u0435 \u0443\u0434\u0430\u0440\u043d\u044b\u0435 \u000d\u000a\u0431\u0435\u0441\u043f\u0438\u043b\u043e\u0442\u043d\u0438\u043a\u0438. \u0414\u043b\u044f \u0438\u0445 \u0443\u043d\u0438\u0447\u0442\u043e\u0436\u0435\u043d\u0438\u044f \u0441\u0442\u0440\u0430\u043d\u044b \u000d\u000a\u041f\u0435\u0440\u0441\u0438\u0434\u0441\u043a\u043e\u0433\u043e \u0437\u0430\u043b\u0438\u0432\u0430 \u0438 \u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u0438\u0435 \u0441\u0438\u043b\u044b \u000d\u000a\u0432 \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u043c \u0437\u0430\u0434\u0435\u0439\u0441\u0442\u0432\u0443\u044e\u0442 \u0434\u043e\u0440\u043e\u0433\u0438\u0435 \u0440\u0430\u043a\u0435\u0442\u044b\u043f\u0435\u0440\u0435\u0445\u0432\u0430\u0442\u0447\u0438\u043a\u0438. \u041f\u043e \u043e\u0446\u0435\u043d\u043a\u0430\u043c Terra Drone, \u043e\u0434\u043d\u0430 \u000d\u000a\u0440\u0430\u043a\u0435\u0442\u0430 Patriot \u0441\u0442\u043e\u0438\u0442 \u043e\u043a\u043e\u043b\u043e $4 \u043c\u043b\u043d, \u0442\u043e\u0433\u0434\u0430 \u043a\u0430\u043a \u000d\u000a\u0438\u0440\u0430\u043d\u0441\u043a\u0438\u0439 \u0431\u0435\u0441\u043f\u0438\u043b\u043e\u0442\u043d\u0438\u043a Shahed \u043e\u0446\u0435\u043d\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u000d\u000a\u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e \u0432 $20 \u0442\u044b\u0441.\u000d\u000a#\u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430 #\u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u044b\u000d\u000a\u0422\u0440\u0430\u043c\u043f \u0437\u0430\u044f\u0432\u0438\u043b, \u0447\u0442\u043e \u0434\u043e\u0441\u0442\u0438\u0447\u044c \u043f\u0435\u0440\u0435\u043c\u0438\u0440\u0438\u044f \u2028\u000d\u000a\u0441 \u0418\u0440\u0430\u043d\u043e\u043c \u043f\u043e\u043c\u043e\u0433 \u041f\u0435\u043a\u0438\u043d\u000d\u000a\u041d\u043e\u0432\u043e\u0441\u0442\u044c \u043e \u0441\u043e\u0433\u043b\u0430\u0448\u0435\u043d\u0438\u0438 \u043f\u0440\u0438\u0448\u043b\u0430 \u0437\u0430 \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0447\u0430\u0441\u043e\u0432 \u0434\u043e \u0434\u0435\u0434\u043b\u0430\u0439\u043d\u0430, \u043f\u043e\u0441\u043b\u0435 \u043a\u043e\u0442\u043e\u0440\u043e\u0433\u043e \u000d\u000a\u0422\u0440\u0430\u043c\u043f \u0433\u0440\u043e\u0437\u0438\u043b\u0441\u044f \u0443\u043d\u0438\u0447\u0442\u043e\u0436\u0438\u0442\u044c \u0446\u0438\u0432\u0438\u043b\u0438\u0437\u0430\u0446\u0438\u044e \u0432 \u0418\u0440\u0430\u043d\u0435. \u000d\u000a\u041f\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442 \u0421\u0428\u0410 \u0414\u043e\u043d\u0430\u043b\u044c\u0434 \u0422\u0440\u0430\u043c\u043f \u0437\u0430\u044f\u0432\u0438\u043b \u000d\u000a\u0432\u043e \u0432\u0442\u043e\u0440\u043d\u0438\u043a \u0430\u0433\u0435\u043d\u0442\u0441\u0442\u0432\u0443 AFP, \u0447\u0442\u043e, \u043f\u043e \u0435\u0433\u043e \u043c\u043d\u0435\u043d\u0438\u044e, \u000d\u000a\u041a\u0438\u0442\u0430\u044e \u0443\u0434\u0430\u043b\u043e\u0441\u044c \u0443\u0431\u0435\u0434\u0438\u0442\u044c \u0418\u0440\u0430\u043d \u0434\u043e\u0433\u043e\u0432\u043e\u0440\u0438\u0442\u044c\u0441\u044f \u000d\u000a\u043e \u043f\u0440\u0435\u043a\u0440\u0430\u0449\u0435\u043d\u0438\u0438 \u043e\u0433\u043d\u044f \u0432 \u0432\u043e\u0439\u043d\u0435 \u043f\u0440\u043e\u0442\u0438\u0432 \u0418\u0437\u0440\u0430\u0438\u043b\u044f \u000d\u000a\u0438 \u0421\u043e\u0435\u0434\u0438\u043d\u0435\u043d\u043d\u044b\u0445 \u0428\u0442\u0430\u0442\u043e\u0432. \u041c\u0418\u0414 \u041a\u041d\u0420 \u000d\u000a\u043f\u0440\u0438\u0432\u0435\u0442\u0441\u0442\u0432\u043e\u0432\u0430\u043b \u044d\u0442\u0438 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f, \u0434\u043e\u0431\u0430\u0432\u0438\u0432, \u0447\u0442\u043e \u041a\u0438\u0442\u0430\u0439 \u000d\u000a\u043f\u0440\u0435\u0434\u043f\u0440\u0438\u043d\u044f\u043b \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0435 \u0443\u0441\u0438\u043b\u0438\u044f \u0434\u043b\u044f \u000d\u000a\u0434\u043e\u0441\u0442\u0438\u0436\u0435\u043d\u0438\u044f \u043f\u0440\u043e\u0447\u043d\u043e\u0433\u043e \u043c\u0438\u0440\u0430 \u043d\u0430 \u0411\u043b\u0438\u0436\u043d\u0435\u043c \u0412\u043e\u0441\u0442\u043e\u043a\u0435.\u000a\u000d\u000a\u0421\u043e \u0441\u0442\u043e\u0440\u043e\u043d\u044b \u0422\u0440\u0430\u043c\u043f\u0430 \u043f\u0440\u0438\u0437\u043d\u0430\u043d\u0438\u0435 \u0437\u0430\u0441\u043b\u0443\u0433 \u041f\u0435\u043a\u0438\u043d\u0430 \u000d\u000a\u043c\u043e\u0436\u0435\u0442 \u043e\u0437\u043d\u0430\u0447\u0430\u0442\u044c \u0434\u0438\u043f\u043b\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0436\u0435\u0441\u0442 \u000d\u000a\u043f\u0440\u0438\u043c\u0438\u0440\u0435\u043d\u0438\u044f. \u0412\u0441\u0435\u0433\u043e \u0434\u043d\u0435\u043c \u0440\u0430\u043d\u0435\u0435 \u0420\u043e\u0441\u0441\u0438\u044f \u0438 \u041a\u0438\u0442\u0430\u0439 \u000d\u000a\u043d\u0430\u043b\u043e\u0436\u0438\u043b\u0438 \u0432\u0435\u0442\u043e \u043d\u0430 \u0440\u0435\u0437\u043e\u043b\u044e\u0446\u0438\u044e \u041e\u041e\u041d \u043e \u0437\u0430\u0449\u0438\u0442\u0435 \u000d\u000a\u0441\u0443\u0434\u043e\u0445\u043e\u0434\u0441\u0442\u0432\u0430 \u0432 \u041e\u0440\u043c\u0443\u0437\u0441\u043a\u043e\u043c \u043f\u0440\u043e\u043b\u0438\u0432\u0435, \u043a\u043e\u0442\u043e\u0440\u0443\u044e \u000d\u000a\u043b\u043e\u0431\u0431\u0438\u0440\u043e\u0432\u0430\u043b \u0412\u0430\u0448\u0438\u043d\u0433\u0442\u043e\u043d. \u041f\u043e\u0441\u0442\u043e\u044f\u043d\u043d\u044b\u0439 \u000d\u000a\u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u0438\u0442\u0435\u043b\u044c \u041a\u0438\u0442\u0430\u044f \u0432 \u041e\u041e\u041d \u0424\u0443 \u0426\u0443\u043d \u0437\u0430\u044f\u0432\u0438\u043b, \u0447\u0442\u043e \u000d\u000a\u043f\u0440\u0438\u043d\u044f\u0442\u0438\u0435 \u0442\u0430\u043a\u043e\u0433\u043e \u043f\u0440\u043e\u0435\u043a\u0442\u0430 \u0432 \u0442\u043e \u0432\u0440\u0435\u043c\u044f, \u043a\u043e\u0433\u0434\u0430 \u0421\u0428\u0410 \u000d\u000a\u0443\u0433\u0440\u043e\u0436\u0430\u044e\u0442 \u0432\u044b\u0436\u0438\u0432\u0430\u043d\u0438\u044e \u0446\u0438\u0432\u0438\u043b\u0438\u0437\u0430\u0446\u0438\u0438, \u043f\u043e\u0441\u043b\u0430\u043b\u043e \u0431\u044b \u000d\u000a\u043d\u0435\u0432\u0435\u0440\u043d\u044b\u0439 \u0441\u0438\u0433\u043d\u0430\u043b. \u041f\u043e\u0441\u0442\u043f\u0440\u0435\u0434 \u0421\u0428\u0410 \u043f\u0440\u0438 \u041e\u041e\u041d \u2028\u000d\u000a\u041c\u0430\u0439\u043a \u0423\u043e\u043b\u0442\u0446 \u043e\u0441\u0443\u0434\u0438\u043b \u0432\u0435\u0442\u043e \u0420\u043e\u0441\u0441\u0438\u0438 \u0438 \u041a\u0438\u0442\u0430\u044f.\u000a\u000d\u000a\u041d\u043e \u0437\u0430 \u043d\u0435\u0434\u0435\u043b\u044e \u0434\u043e \u043f\u0440\u0435\u0434\u043f\u043e\u043b\u043e\u0436\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0433\u043e \u0432\u0438\u0437\u0438\u0442\u0430 \u000d\u000a\u0422\u0440\u0430\u043c\u043f\u0430 \u0432 \u041f\u0435\u043a\u0438\u043d \u0433\u0440\u0430\u0434\u0443\u0441 \u043f\u0440\u043e\u0442\u0438\u0432\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u044f, \u0432\u0438\u0434\u0438\u043c\u043e, \u000d\u000a\u0440\u0435\u0448\u0435\u043d\u043e \u0431\u044b\u043b\u043e \u043d\u0435 \u043f\u043e\u0434\u043d\u0438\u043c\u0430\u0442\u044c, \u0432\u0435\u0434\u044c \u043d\u0430 \u0432\u0441\u0442\u0440\u0435\u0447\u0435 \u000d\u000a\u0441 \u0421\u0438 \u0426\u0437\u0438\u043d\u044c\u043f\u0438\u043d\u043e\u043c \u0430\u043c\u0435\u0440\u0438\u043a\u0430\u043d\u0441\u043a\u0438\u0439 \u043f\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442 \u0431\u0443\u0434\u0435\u0442 \u000d\u000a\u043e\u0431\u0441\u0443\u0436\u0434\u0430\u0442\u044c \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u044b\u0435 \u0432\u044b\u0445\u043e\u0434\u044b \u0438\u0437 \u0442\u043e\u0440\u0433\u043e\u0432\u043e\u0439 \u000d\u000a\u0432\u043e\u0439\u043d\u044b, \u0431\u043e\u043b\u044c\u043d\u043e \u0431\u044c\u044e\u0449\u0435\u0439 \u043f\u043e \u044d\u043a\u043e\u043d\u043e\u043c\u0438\u043a\u0430\u043c \u043e\u0431\u0435\u0438\u0445 \u000d\u000a\u0441\u0442\u0440\u0430\u043d.\u000d\u000a06 09","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 3\u201310 \u0430\u043f\u0440\u0435\u043b\u044f 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b #\u043f\u0440\u043e\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u043e\u0441\u0442\u044c\u000d\u000aEVE Energy Co. \u043f\u043e\u0441\u0442\u0440\u043e\u0438\u0442 \u0434\u0432\u0430 \u043d\u043e\u0432\u044b\u0445 \u0437\u0430\u0432\u043e\u0434\u0430 \u2028\u000d\u000a\u043b\u0438\u0442\u0438\u0439\u0438\u043e\u043d\u043d\u044b\u0445 \u0430\u043a\u043a\u0443\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u043e\u0432 \u000d\u000a\u041e\u0431\u0449\u0430\u044f \u0433\u043e\u0434\u043e\u0432\u0430\u044f \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044c 110 \u0413\u0412\u0442\u00b7\u0447, \u043e\u0431\u044a\u0435\u043c \u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0439 \u2014 $1,6 \u043c\u043b\u0440\u0434.\u000d\u000aEVE Energy Co., \u043e\u0434\u0438\u043d \u0438\u0437 \u0432\u0435\u0434\u0443\u0449\u0438\u0445 \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u0445 \u000d\u000a\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u0439 \u043b\u0438\u0442\u0438\u0439\u0438\u043e\u043d\u043d\u044b\u0445 \u0430\u043a\u043a\u0443\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u043e\u0432, \u000d\u000a\u0437\u0430\u044f\u0432\u0438\u043b \u043e \u043f\u043b\u0430\u043d\u0430\u0445 \u043f\u043e\u0441\u0442\u0440\u043e\u0438\u0442\u044c \u0434\u0432\u0430 \u043d\u043e\u0432\u044b\u0445 \u0437\u0430\u0432\u043e\u0434\u0430 \u000d\u000a\u043e\u0431\u0449\u0435\u0439 \u0433\u043e\u0434\u043e\u0432\u043e\u0439 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044c\u044e 110 \u0413\u0412\u0442\u00b7\u0447 \u000d\u000a\u0438 \u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u044c\u044e 11 \u043c\u043b\u0440\u0434 \u044e\u0430\u043d\u0435\u0439 ($1,6 \u043c\u043b\u0440\u0434).\u000a\u000d\u000a\u041f\u043b\u0430\u043d \u0432\u043a\u043b\u044e\u0447\u0430\u0435\u0442 \u0441\u043e\u0437\u0434\u0430\u043d\u0438\u0435 \u0421\u041f \u0441 Fujian Longking \u000d\u000aCo. \u043d\u0430 \u044e\u0433\u0435 \u041a\u0438\u0442\u0430\u044f \u0437\u0430 6 \u043c\u043b\u0440\u0434 \u044e\u0430\u043d\u0435\u0439 \u0438 \u0441 \u0433\u043e\u0434\u043e\u0432\u043e\u0439 \u000d\u000a\u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044c\u044e 60 \u0413\u0412\u0442\u00b7\u0447, \u0430 \u0442\u0430\u043a\u0436\u0435 \u0441\u0442\u0440\u043e\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u000d\u000a\u043d\u0430 \u0432\u043e\u0441\u0442\u043e\u043a\u0435 \u0441\u0442\u0440\u0430\u043d\u044b \u0437\u0430\u0432\u043e\u0434\u0430 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044c\u044e 50 \u0413\u0412\u0442\u00b7\u0447, \u000d\u000a\u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u0431\u0443\u0434\u0435\u0442 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u044c \u0441\u0442\u0430\u0446\u0438\u043e\u043d\u0430\u0440\u043d\u044b\u0435 \u000d\u000a\u0430\u043a\u043a\u0443\u043c\u0443\u043b\u044f\u0442\u043e\u0440\u044b \u0438 \u0431\u0430\u0442\u0430\u0440\u0435\u0438 \u0434\u043b\u044f \u044d\u043b\u0435\u043a\u0442\u0440\u043e\u043c\u043e\u0431\u0438\u043b\u0435\u0439. \u000d\u000a\u0418\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0438 \u0441\u043e\u0441\u0442\u0430\u0432\u044f\u0442 5 \u043c\u043b\u0440\u0434 \u044e\u0430\u043d\u0435\u0439.\u000a\u000d\u000a\u0420\u0430\u043d\u0435\u0435, \u0432 \u043c\u0430\u0440\u0442\u0435, EVE Energy Co. \u0443\u0436\u0435 \u043e\u0431\u044a\u044f\u0432\u043b\u044f\u043b\u0430 \u000d\u000a\u043e \u0441\u0442\u0440\u043e\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0435 \u0435\u0449\u0435 \u0434\u0432\u0443\u0445 \u0437\u0430\u0432\u043e\u0434\u043e\u0432 \u043d\u0430 \u044e\u0433\u0435 \u041a\u0438\u0442\u0430\u044f \u000d\u000a\u043e\u0431\u0449\u0435\u0439 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044c\u044e 120 \u0413\u0412\u0442\u00b7\u0447 \u0438 \u0441\u0443\u043c\u043c\u0430\u0440\u043d\u044b\u043c\u0438 \u000d\u000a\u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u044f\u043c\u0438 \u0432 12 \u043c\u043b\u0440\u0434 \u044e\u0430\u043d\u0435\u0439.\u000d\u000a#\u043b\u043e\u0433\u0438\u0441\u0442\u0438\u043a\u0430\u000d\u000a\u041a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u0435 \u0434\u043e\u0431\u044b\u0442\u0447\u0438\u043a\u0438 \u043c\u0435\u0434\u0438 \u043c\u043e\u0434\u0435\u0440\u043d\u0438\u0437\u0438\u0440\u0443\u044e\u0442 \u000d\u000a\u0436\u0435\u043b\u0435\u0437\u043d\u0443\u044e \u0434\u043e\u0440\u043e\u0433\u0443 \u0417\u0430\u043c\u0431\u0438\u044f \u0422\u0430\u043d\u0437\u0430\u043d\u0438\u044f\u000d\u000a\u0427\u0442\u043e\u0431\u044b \u0440\u0435\u0430\u043d\u0438\u043c\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u0432\u0435\u0442\u043a\u0443, \u043f\u043e\u0441\u0442\u0440\u043e\u0435\u043d\u043d\u0443\u044e \u043f\u0440\u0438 \u041c\u0430\u043e \u0426\u0437\u044d\u0434\u0443\u043d\u0435, \u043f\u043e\u0442\u0440\u0435\u0431\u0443\u0435\u0442\u0441\u044f $1,24 \u043c\u043b\u0440\u0434. \u000d\u000a\u041a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u0435 CMOC Group Ltd. \u0438 Zijin Mining Group \u000d\u000aCo. \u043e\u0431\u044a\u0435\u0434\u0438\u043d\u0438\u043b\u0438\u0441\u044c \u0441\u043e \u0441\u0442\u0440\u043e\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0439 \u000d\u000a\u0433\u043e\u0441\u043a\u043e\u0440\u043f\u043e\u0440\u0430\u0446\u0438\u0435\u0439 China Civil Engineering \u000d\u000aConstruction Corp. (CCECC) \u0434\u043b\u044f \u043c\u043e\u0434\u0435\u0440\u043d\u0438\u0437\u0430\u0446\u0438\u0438 \u000d\u000a1860 \u043a\u0438\u043b\u043e\u043c\u0435\u0442\u0440\u043e\u0432\u043e\u0439 \u0436\u0435\u043b\u0435\u0437\u043d\u043e\u0434\u043e\u0440\u043e\u0436\u043d\u043e\u0439 \u043b\u0438\u043d\u0438\u0438 \u000d\u000a\u041a\u0430\u043f\u0438\u0440\u0438-\u041c\u043f\u043e\u0448\u0438 \u2014 \u0414\u0430\u0440 \u044d\u0441 \u0421\u0430\u043b\u0430\u043c. CCECC \u000d\u000a\u0441\u043e\u0445\u0440\u0430\u043d\u0438\u0442 80% \u0430\u043a\u0446\u0438\u0439 \u0432 \u0421\u041f, \u0440\u0435\u0430\u043b\u0438\u0437\u0443\u044e\u0449\u0435\u043c \u043f\u0440\u043e\u0435\u043a\u0442 \u000d\u000a\u043d\u0430 \u0443\u0441\u043b\u043e\u0432\u0438\u044f\u0445 30 \u043b\u0435\u0442\u043d\u0435\u0439 \u043a\u043e\u043d\u0446\u0435\u0441\u0441\u0438\u0438. \u0414\u0440\u0443\u0433\u0438\u0435 \u000d\u000a\u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u0438 \u043f\u043e\u043b\u0443\u0447\u0430\u0442 \u043f\u043e 5%.\u000a\u000d\u000a\u0412\u0435\u0442\u043a\u0430, \u043f\u0435\u0440\u0432\u043e\u043d\u0430\u0447\u0430\u043b\u044c\u043d\u043e \u043f\u043e\u0441\u0442\u0440\u043e\u0435\u043d\u043d\u0430\u044f \u043f\u0440\u0438 \u000d\u000a\u0441\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0438 \u041f\u0435\u043a\u0438\u043d\u0430 \u043f\u0440\u0438 \u041c\u0430\u043e \u0426\u0437\u044d\u0434\u0443\u043d\u0435 \u2028\u000d\u000a\u0432 1970 \u0435 \u0433\u043e\u0434\u044b, \u0441\u043e\u0435\u0434\u0438\u043d\u044f\u0435\u0442 \u0431\u043e\u0433\u0430\u0442\u0443\u044e \u043d\u0435\u0444\u0442\u044c\u044e \u000d\u000a\u0446\u0435\u043d\u0442\u0440\u0430\u043b\u044c\u043d\u0443\u044e \u0447\u0430\u0441\u0442\u044c \u0417\u0430\u043c\u0431\u0438\u0438 \u0441 \u043f\u043e\u0440\u0442\u043e\u043c \u000d\u000a\u043d\u0430 \u043f\u043e\u0431\u0435\u0440\u0435\u0436\u044c\u0435 \u0422\u0430\u043d\u0437\u0430\u043d\u0438\u0438, \u043e\u0442\u043a\u0443\u0434\u0430 \u0440\u0435\u0441\u0443\u0440\u0441\u044b \u2028\u000d\u000a\u0443\u0434\u043e\u0431\u043d\u043e \u0432\u044b\u0432\u043e\u0437\u0438\u0442\u044c \u0432 \u041a\u0438\u0442\u0430\u0439.\u000a\u000d\u000a\u0416\u0435\u043b\u0435\u0437\u043d\u043e\u0434\u043e\u0440\u043e\u0436\u043d\u0430\u044f \u043b\u0438\u043d\u0438\u044f \u0422\u0430\u0437\u0430\u0440\u0430 \u043d\u0430 \u0431\u043e\u043b\u044c\u0448\u0435\u0439 \u000d\u000a\u0447\u0430\u0441\u0442\u0438 \u043f\u0443\u0442\u0438 \u2014 \u043e\u0434\u043d\u043e\u043a\u043e\u043b\u0435\u0439\u043d\u0430\u044f. \u041f\u043e\u0441\u043b\u0435 \u000d\u000a\u043c\u043e\u0434\u0435\u0440\u043d\u0438\u0437\u0430\u0446\u0438\u0438 \u043e\u043d\u0430 \u0441\u043c\u043e\u0436\u0435\u0442 \u0432\u0437\u044f\u0442\u044c \u043d\u0430 \u0441\u0435\u0431\u044f \u000d\u000a\u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0439 \u043e\u0431\u044a\u0435\u043c \u0437\u0430\u043c\u0431\u0438\u0439\u0441\u043a\u0438\u0445 \u0438 \u043a\u043e\u043d\u0433\u043e\u043b\u0435\u0437\u0441\u043a\u0438\u0445 \u000d\u000a\u043f\u0435\u0440\u0435\u0432\u043e\u0437\u043e\u043a \u043c\u0435\u0442\u0430\u043b\u043b\u0443\u0440\u0433\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u043f\u0440\u043e\u0434\u0443\u043a\u0446\u0438\u0438, \u0447\u0430\u0441\u0442\u044c \u000d\u000a\u043a\u043e\u0442\u043e\u0440\u043e\u0439 \u0434\u043e \u0441\u0438\u0445 \u043f\u043e\u0440 \u0442\u0440\u0430\u043d\u0441\u043f\u043e\u0440\u0442\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u000d\u000a\u0430\u0432\u0442\u043e\u043c\u043e\u0431\u0438\u043b\u044f\u043c\u0438 \u043d\u0430 \u0431\u043e\u043b\u044c\u0448\u0438\u0435 \u0440\u0430\u0441\u0441\u0442\u043e\u044f\u043d\u0438\u044f.\u000a\u000d\u000a\u041c\u043e\u0434\u0435\u0440\u043d\u0438\u0437\u0430\u0446\u0438\u044f \u043b\u043e\u0433\u0438\u0441\u0442\u0438\u043a\u0438 \u043f\u0440\u043e\u0445\u043e\u0434\u0438\u0442 \u043d\u0430 \u0444\u043e\u043d\u0435 \u000d\u000a\u043f\u043e\u043f\u044b\u0442\u043e\u043a \u0412\u0430\u0448\u0438\u043d\u0433\u0442\u043e\u043d\u0430 \u043e\u0441\u043b\u0430\u0431\u0438\u0442\u044c \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u041f\u0435\u043a\u0438\u043d\u0430 \u000d\u000a\u043d\u0430\u0434 \u0446\u0435\u043f\u043e\u0447\u043a\u0430\u043c\u0438 \u043f\u043e\u0441\u0442\u0430\u0432\u043e\u043a \u043a\u0440\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u0432\u0430\u0436\u043d\u044b\u0445 \u000d\u000a\u043c\u0438\u043d\u0435\u0440\u0430\u043b\u043e\u0432 \u0432 \u0410\u0444\u0440\u0438\u043a\u0435. \u000d\u000a07 09","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 3\u201310 \u0430\u043f\u0440\u0435\u043b\u044f 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b #\u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430\u000d\u000a\u041f\u0435\u0440\u0435\u0433\u043e\u0432\u043e\u0440\u044b \u041a\u041d\u0420 \u0438 \u0410\u0432\u0441\u0442\u0440\u0430\u043b\u0438\u0438 \u043f\u043e \u0436\u0435\u043b\u0435\u0437\u043d\u043e\u0439 \u0440\u0443\u0434\u0435 \u000d\u000a\u0432\u0441\u0442\u0443\u043f\u0438\u043b\u0438 \u0432 \u0440\u0435\u0448\u0430\u044e\u0449\u0443\u044e \u0444\u0430\u0437\u0443\u000d\u000a\u041a\u041d\u0420 \u0431\u0440\u043e\u0441\u0430\u0435\u0442 \u0432\u044b\u0437\u043e\u0432 \u0430\u0432\u0441\u0442\u0440\u0430\u043b\u0438\u0439\u0441\u043a\u0438\u043c \u0433\u043e\u0440\u043d\u043e\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0438\u043c \u0433\u0438\u0433\u0430\u043d\u0442\u0430\u043c, \u0447\u0442\u043e\u0431\u044b \u043f\u0435\u0440\u0435\u0441\u0442\u0440\u043e\u0438\u0442\u044c \u0440\u044b\u043d\u043e\u043a \u000d\u000a\u043e\u0431\u044a\u0435\u043c\u043e\u043c $190 \u043c\u043b\u0440\u0434. \u000d\u000a\u041d\u0430\u043f\u0440\u044f\u0436\u0435\u043d\u043d\u044b\u0435 \u043f\u0435\u0440\u0435\u0433\u043e\u0432\u043e\u0440\u044b \u043f\u043e \u0446\u0435\u043d\u0435 \u043d\u0430 \u0436\u0435\u043b\u0435\u0437\u043d\u0443\u044e \u000d\u000a\u0440\u0443\u0434\u0443 \u043c\u0435\u0436\u0434\u0443 \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u043c \u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u043c \u000d\u000a\u0442\u0440\u0435\u0439\u0434\u0435\u0440\u043e\u043c China Mineral Resources Group \u000d\u000a\u0438 \u0430\u0432\u0441\u0442\u0440\u0430\u043b\u0438\u0439\u0441\u043a\u0438\u043c \u0433\u043e\u0440\u043d\u043e\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0438\u043c \u0433\u0438\u0433\u0430\u043d\u0442\u043e\u043c \u000d\u000aBHP \u0432\u0441\u0442\u0443\u043f\u0438\u043b\u0438 \u0432 \u043d\u043e\u0432\u0443\u044e \u0444\u0430\u0437\u0443, \u0441\u043e\u043e\u0431\u0449\u0430\u0435\u0442 \u000d\u000aBloomberg. \u000a\u000d\u000aChina Mineral Resources Group \u2014 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f, \u000d\u000a\u043d\u0430\u043f\u0440\u044f\u043c\u0443\u044e \u043f\u043e\u0434\u0447\u0438\u043d\u0435\u043d\u043d\u0430\u044f \u0446\u0435\u043d\u0442\u0440\u0430\u043b\u044c\u043d\u043e\u043c\u0443 \u000d\u000a\u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0443 \u041a\u041d\u0420, \u2014 \u0441 \u043e\u0441\u0435\u043d\u0438 2025 \u0433\u043e\u0434\u0430 \u000d\u000a\u043d\u0430\u0445\u043e\u0434\u0438\u0442\u0441\u044f \u0432 \u043a\u043e\u043d\u0444\u0440\u043e\u043d\u0442\u0430\u0446\u0438\u0438 \u0441 BHP, \u043f\u044b\u0442\u0430\u044f\u0441\u044c \u000d\u000a\u0437\u0430\u0441\u0442\u0430\u0432\u0438\u0442\u044c \u0435\u0435 \u043f\u0440\u0438\u043d\u044f\u0442\u044c \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u0443\u044e \u043c\u043e\u0434\u0435\u043b\u044c \u000d\u000a\u0446\u0435\u043d\u043e\u043e\u0431\u0440\u0430\u0437\u043e\u0432\u0430\u043d\u0438\u044f. \u042d\u0442\u043e \u043c\u043e\u0436\u0435\u0442 \u043f\u0440\u0438\u0432\u0435\u0441\u0442\u0438 \u000d\u000a\u043a \u043f\u0435\u0440\u0435\u0441\u0442\u0440\u043e\u0439\u043a\u0435 \u0432\u0441\u0435\u0433\u043e \u0440\u044b\u043d\u043a\u0430 \u043e\u0431\u044a\u0435\u043c\u043e\u043c $190 \u043c\u043b\u0440\u0434.  \u000d\u000a\u041a\u0430\u043a \u0441\u043e\u043e\u0431\u0449\u0430\u0435\u0442\u0441\u044f \u0432 \u0441\u0442\u0430\u0442\u044c\u0435, \u0434\u0440\u0443\u0433\u0438\u0435 \u0430\u0432\u0441\u0442\u0440\u0430\u043b\u0438\u0439\u0441\u043a\u0438\u0435 \u000d\u000a\u0433\u043e\u0440\u043d\u043e\u0434\u043e\u0431\u044b\u0432\u0430\u044e\u0449\u0438\u0435 \u0433\u0438\u0433\u0430\u043d\u0442\u044b \u2014 Rio Tinto \u000d\u000a\u0438 Fortescue \u2014 \u0443\u0436\u0435 \u0441\u043e\u0433\u043b\u0430\u0441\u0438\u043b\u0438\u0441\u044c \u0438\u0437\u043c\u0435\u043d\u0438\u0442\u044c \u000d\u000a\u0446\u0435\u043d\u043e\u0432\u044b\u0435 \u043e\u0440\u0438\u0435\u043d\u0442\u0438\u0440\u044b. CMRG, \u0432\u043e\u0437\u0433\u043b\u0430\u0432\u043b\u044f\u0435\u043c\u0430\u044f \u000d\u000a\u0432\u0435\u0442\u0435\u0440\u0430\u043d\u043e\u043c \u043e\u0442\u0440\u0430\u0441\u043b\u0438 \u042f\u043e \u041b\u0438\u043d\u0435\u043c, \u0438\u043c\u0435\u044e\u0449\u0438\u043c \u043f\u0440\u044f\u043c\u0443\u044e \u000d\u000a\u0441\u0432\u044f\u0437\u044c \u0441 \u044d\u043a\u043e\u043d\u043e\u043c\u0438\u0447\u0435\u0441\u043a\u0438\u043c \u0441\u043e\u0432\u0435\u0442\u043d\u0438\u043a\u043e\u043c \u043f\u0440\u0435\u0437\u0438\u0434\u0435\u043d\u0442\u0430 \u000d\u000a\u0421\u0438 \u0426\u0437\u0438\u043d\u044c\u043f\u0438\u043d\u0430, \u043f\u043e\u044f\u0432\u0438\u043b\u0430\u0441\u044c \u043d\u0430 \u0440\u044b\u043d\u043a\u0435 \u0432 2022 \u0433\u043e\u0434\u0443. \u000d\u000a\u042d\u043a\u0441\u043f\u0435\u0440\u0442\u044b, \u043e\u043f\u0440\u043e\u0448\u0435\u043d\u043d\u044b\u0435 \u0430\u0433\u0435\u043d\u0442\u0441\u0442\u0432\u043e\u043c, \u043f\u043e\u043b\u0430\u0433\u0430\u044e\u0442, \u000d\u000a\u0447\u0442\u043e \u044d\u0442\u0430 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u044f \u2014 \u0447\u0430\u0441\u0442\u044c \u0433\u0435\u043e\u043f\u043e\u043b\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u000d\u000a\u043f\u043b\u0430\u043d\u0430 \u043f\u043e \u043f\u0435\u0440\u0435\u0445\u043e\u0434\u0443 \u041a\u0438\u0442\u0430\u044f \u043e\u0442 \u0440\u043e\u043b\u0438 \u043a\u0440\u0443\u043f\u043d\u0435\u0439\u0448\u0435\u0433\u043e \u000d\u000a\u043f\u043e\u043a\u0443\u043f\u0430\u0442\u0435\u043b\u044f \u0440\u0435\u0441\u0443\u0440\u0441\u043e\u0432 \u043a \u0440\u043e\u043b\u0438 \u0446\u0435\u043d\u043e\u043e\u0431\u0440\u0430\u0437\u043e\u0432\u0430\u0442\u0435\u043b\u044f.\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b #\u043d\u0430\u043b\u043e\u0433\u0438\u000d\u000a\u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u044f \u0441\u043a\u043e\u0440\u043e \u043f\u043e\u0432\u044b\u0441\u0438\u0442 \u0441\u0431\u043e\u0440\u044b \u2028\u000d\u000a\u0441 \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u0435\u0440\u043e\u0432 \u043d\u0438\u043a\u0435\u043b\u044f\u000d\u000a\u0415\u0449\u0435 \u043d\u0435\u0434\u0435\u043b\u044e \u043d\u0430\u0437\u0430\u0434 \u0441\u043e\u043e\u0431\u0449\u0430\u043b\u043e\u0441\u044c, \u0447\u0442\u043e \u043f\u0440\u0430\u0432\u0438\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u043e \u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0438 \u043e\u0442\u043a\u043b\u0430\u0434\u044b\u0432\u0430\u0435\u0442 \u0438\u0445 \u0432\u0432\u0435\u0434\u0435\u043d\u0438\u0435.\u000d\u000a\u041c\u0438\u043d\u0438\u0441\u0442\u0435\u0440\u0441\u0442\u0432\u043e \u044d\u043d\u0435\u0440\u0433\u0435\u0442\u0438\u043a\u0438 \u0438 \u043c\u0438\u043d\u0435\u0440\u0430\u043b\u044c\u043d\u044b\u0445 \u000d\u000a\u0440\u0435\u0441\u0443\u0440\u0441\u043e\u0432 \u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0438 (ESDM) \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u0435\u0442 \u000d\u000a\u043f\u0435\u0440\u0435\u0441\u043c\u043e\u0442\u0440 \u0444\u043e\u0440\u043c\u0443\u043b\u044b \u0431\u0430\u0437\u043e\u0432\u043e\u0439 \u0446\u0435\u043d\u044b \u043d\u0430 \u043d\u0438\u043a\u0435\u043b\u044c \u000d\u000a(HPM), \u0432\u043d\u0435\u0434\u0440\u0435\u043d\u0438\u0435 \u043a\u043e\u0442\u043e\u0440\u043e\u0439 \u0437\u0430\u043f\u043b\u0430\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043e \u000d\u000a\u043d\u0430 \u0430\u043f\u0440\u0435\u043b\u044c 2026 \u0433\u043e\u0434\u0430. \u000a\u000d\u000a\u0413\u0435\u043d\u0435\u0440\u0430\u043b\u044c\u043d\u044b\u0439 \u0434\u0438\u0440\u0435\u043a\u0442\u043e\u0440 \u043f\u043e \u043c\u0438\u043d\u0435\u0440\u0430\u043b\u044c\u043d\u044b\u043c \u000d\u000a\u0440\u0435\u0441\u0443\u0440\u0441\u0430\u043c \u0438 \u0443\u0433\u043b\u044e \u0422\u0440\u0438 \u0412\u0438\u043d\u0430\u0440\u043d\u043e \u0437\u0430\u044f\u0432\u0438\u043b, \u0447\u0442\u043e \u000d\u000a\u0442\u0435\u043a\u0443\u0449\u0430\u044f \u0444\u043e\u0440\u043c\u0443\u043b\u0430 HPM \u0431\u043e\u043b\u044c\u0448\u0435 \u043d\u0435 \u043e\u0442\u0440\u0430\u0436\u0430\u0435\u0442 \u000d\u000a\u0444\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u0443\u044e \u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u044c \u0441\u0434\u0435\u043b\u043e\u043a, \u043f\u043e\u0441\u043a\u043e\u043b\u044c\u043a\u0443 \u000d\u000a\u043d\u0435 \u0443\u0447\u0438\u0442\u044b\u0432\u0430\u0435\u0442 \u00ab\u0440\u044b\u043d\u043e\u0447\u043d\u044b\u0435 \u043f\u0440\u0435\u043c\u0438\u0438\u00bb, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u000d\u000a\u0432 \u043d\u0430\u0441\u0442\u043e\u044f\u0449\u0435\u0435 \u0432\u0440\u0435\u043c\u044f \u0432\u044b\u043f\u043b\u0430\u0447\u0438\u0432\u0430\u044e\u0442 \u043f\u043b\u0430\u0432\u0438\u043b\u044c\u043d\u044b\u0435 \u000d\u000a\u0437\u0430\u0432\u043e\u0434\u044b.\u000a\u000d\u000a\u0414\u043e\u0440\u0430\u0431\u043e\u0442\u043a\u0438 \u0432\u043a\u043b\u044e\u0447\u0430\u0442 \u044d\u0442\u0438 \u043f\u0440\u0435\u043c\u0438\u0438 \u0432 \u0440\u0430\u0441\u0447\u0435\u0442\u044b \u0440\u043e\u044f\u043b\u0442\u0438 \u000d\u000a\u0432 \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0435 \u043f\u0435\u0440\u0435\u043c\u0435\u043d\u043d\u044b\u0445 \u0438 \u0442\u0435\u043c \u0441\u0430\u043c\u044b\u043c \u043e\u0431\u0435\u0441\u043f\u0435\u0447\u0430\u0442 \u000d\u000a\u0442\u043e\u0447\u043d\u043e\u0435 \u043e\u0442\u0440\u0430\u0436\u0435\u043d\u0438\u0435 \u0432 \u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0445 \u0434\u043e\u0445\u043e\u0434\u0430\u0445 \u000d\u000a\u043f\u043e\u043b\u043d\u043e\u0439 \u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u0438 \u043f\u0440\u043e\u0434\u0430\u0436 \u043d\u0438\u043a\u0435\u043b\u044f, \u0430 HPM \u000d\u000a\u0438\u0437 \u043f\u0440\u043e\u0441\u0442\u043e\u0439 \u00ab\u043c\u0438\u043d\u0438\u043c\u0430\u043b\u044c\u043d\u043e\u0439 \u0446\u0435\u043d\u044b\u00bb \u043f\u0440\u0435\u0432\u0440\u0430\u0442\u0438\u0442\u0441\u044f \u000d\u000a\u0432 \u0440\u0435\u043f\u0440\u0435\u0437\u0435\u043d\u0442\u0430\u0442\u0438\u0432\u043d\u044b\u0439 \u0440\u044b\u043d\u043e\u0447\u043d\u044b\u0439 \u043e\u0440\u0438\u0435\u043d\u0442\u0438\u0440.\u000d\u000a08 09","\u0411\u043b\u0438\u0436\u043d\u0438\u0439 \u0412\u043e\u0441\u0442\u043e\u043a, \u0421\u0435\u0432\u0435\u0440\u043d\u0430\u044f \u0410\u0444\u0440\u0438\u043a\u0430 \u0438 \u041a\u0438\u0442\u0430\u0439 3\u201310 \u0430\u043f\u0440\u0435\u043b\u044f 2026 \u0433\u043e\u0434\u0430\u000d\u000a#\u0440\u0435\u0441\u0443\u0440\u0441\u044b\u000d\u000a\u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u044f \u0443\u0442\u0432\u0435\u0440\u0434\u0438\u043b\u0430 \u043a\u0432\u043e\u0442\u044b \u043d\u0430 \u0434\u043e\u0431\u044b\u0447\u0443 \u043d\u0438\u043a\u0435\u043b\u044f\u000d\u000a\u0414\u0436\u0430\u043a\u0430\u0440\u0442\u0430 \u0441\u0442\u0440\u0435\u043c\u0438\u0442\u0441\u044f \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0438\u0442\u044c \u0434\u043e\u043c\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435 \u043a\u0438\u0442\u0430\u0439\u0441\u043a\u0438\u0445 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0439.\u000d\u000a\u041c\u0438\u043d\u0438\u0441\u0442\u0435\u0440\u0441\u0442\u0432\u043e \u044d\u043d\u0435\u0440\u0433\u0435\u0442\u0438\u043a\u0438 \u0438 \u043c\u0438\u043d\u0435\u0440\u0430\u043b\u044c\u043d\u044b\u0445 \u000d\u000a\u0440\u0435\u0441\u0443\u0440\u0441\u043e\u0432 \u0418\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0438 (ESDM) \u0443\u0442\u0432\u0435\u0440\u0434\u0438\u043b\u043e \u043a\u0432\u043e\u0442\u044b \u000d\u000a\u043d\u0430 \u0434\u043e\u0431\u044b\u0447\u0443 \u043d\u0438\u043a\u0435\u043b\u044f \u0432 \u0440\u0430\u0437\u043c\u0435\u0440\u0435 \u043f\u0440\u0438\u0431\u043b\u0438\u0437\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u000d\u000a190\u2013200 \u043c\u043b\u043d \u0442\u043e\u043d\u043d. \u000a\u000d\u000a\u0413\u0435\u043d\u0435\u0440\u0430\u043b\u044c\u043d\u044b\u0439 \u0434\u0438\u0440\u0435\u043a\u0442\u043e\u0440 \u043f\u043e \u043c\u0438\u043d\u0435\u0440\u0430\u043b\u044c\u043d\u044b\u043c \u000d\u000a\u0440\u0435\u0441\u0443\u0440\u0441\u0430\u043c \u0438 \u0443\u0433\u043b\u044e \u0422\u0440\u0438 \u0412\u0438\u043d\u0430\u0440\u043d\u043e \u043e\u0442\u043c\u0435\u0442\u0438\u043b: \u043d\u0435\u0441\u043c\u043e\u0442\u0440\u044f \u000d\u000a\u043d\u0430 \u0442\u043e, \u0447\u0442\u043e \u0442\u0435\u043a\u0443\u0449\u0438\u0439 \u0441\u043e\u0432\u043e\u043a\u0443\u043f\u043d\u044b\u0439 \u0446\u0435\u043b\u0435\u0432\u043e\u0439 \u000d\u000a\u043f\u043e\u043a\u0430\u0437\u0430\u0442\u0435\u043b\u044c \u0441\u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u0442 \u043e\u0442 260 \u0434\u043e 270 \u043c\u043b\u043d \u0442\u043e\u043d\u043d, \u000d\u000a\u0440\u0430\u0441\u0441\u043c\u0430\u0442\u0440\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e\u0441\u0442\u044c \u043f\u043e\u0441\u0442\u0435\u043f\u0435\u043d\u043d\u043e\u0433\u043e \u000d\u000a\u0441\u043c\u044f\u0433\u0447\u0435\u043d\u0438\u044f \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u0439 \u043d\u0430 \u0434\u043e\u0431\u044b\u0447\u0443.\u000a\u000d\u000a\u0412\u043f\u0440\u043e\u0447\u0435\u043c, \u0440\u0430\u043d\u0435\u0435 \u0441\u043e\u043e\u0431\u0449\u0430\u043b\u043e\u0441\u044c, \u0447\u0442\u043e \u0432\u0441\u043a\u043e\u0440\u0435 \u043c\u043e\u0436\u0435\u0442 \u000d\u000a\u043f\u043e\u044f\u0432\u0438\u0442\u044c\u0441\u044f \u043d\u043e\u0432\u0430\u044f \u043c\u0435\u0440\u0430 \u2014 \u0434\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u0430\u044f \u000d\u000a\u044d\u043a\u0441\u043f\u043e\u0440\u0442\u043d\u0430\u044f \u043f\u043e\u0448\u043b\u0438\u043d\u0430 \u043d\u0430 \u043f\u0435\u0440\u0435\u0440\u0430\u0431\u043e\u0442\u0430\u043d\u043d\u0443\u044e \u000d\u000a\u043d\u0438\u043a\u0435\u043b\u0435\u0432\u0443\u044e \u043f\u0440\u043e\u0434\u0443\u043a\u0446\u0438\u044e.\u000d\u000a#\u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430 #\u0440\u0435\u0441\u0443\u0440\u0441\u044b #\u043f\u0440\u043e\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u043e\u0441\u0442\u044c\u000d\u000a\u041a\u0438\u0442\u0430\u0439 \u0441\u043e\u0437\u0434\u0430\u0435\u0442 \u043d\u043e\u0432\u044b\u0439 \u043c\u0435\u0445\u0430\u043d\u0438\u0437\u043c \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e\u0441\u0442\u0438 \u000d\u000a\u0446\u0435\u043f\u043e\u0447\u0435\u043a \u043f\u043e\u0441\u0442\u0430\u0432\u043e\u043a\u000d\u000a\u041e\u043d \u0434\u0430\u0435\u0442 \u041f\u0435\u043a\u0438\u043d\u0443 \u044e\u0440\u0438\u0434\u0438\u0447\u0435\u0441\u043a\u0443\u044e \u0431\u0430\u0437\u0443 \u0434\u043b\u044f \u0436\u0435\u0441\u0442\u043a\u043e\u0439 \u0431\u043e\u0440\u044c\u0431\u044b \u0441 \u0437\u0430\u0440\u0443\u0431\u0435\u0436\u043d\u044b\u043c\u0438 \u0441\u0430\u043d\u043a\u0446\u0438\u044f\u043c\u0438.\u000d\u000a\u0413\u043e\u0441\u0441\u043e\u0432\u0435\u0442 \u041a\u041d\u0420 \u0432\u044b\u043f\u0443\u0441\u0442\u0438\u043b \u041f\u043e\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u000d\u000a\u043e \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e\u0441\u0442\u0438 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0445 \u0446\u0435\u043f\u043e\u0447\u0435\u043a \u000d\u000a\u0438 \u0446\u0435\u043f\u043e\u0447\u0435\u043a \u043f\u043e\u0441\u0442\u0430\u0432\u043e\u043a \u0432 \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0438\u0439 \u0434\u0435\u043d\u044c \u043c\u0430\u0440\u0442\u0430, \u000d\u000a\u043d\u043e \u0432 \u043f\u043e\u043b\u0435 \u0437\u0440\u0435\u043d\u0438\u044f \u0437\u0430\u043f\u0430\u0434\u043d\u044b\u0445 \u0430\u043d\u0430\u043b\u0438\u0442\u0438\u043a\u043e\u0432 \u043e\u043d\u043e \u000d\u000a\u043f\u043e\u043f\u0430\u043b\u043e \u043b\u0438\u0448\u044c \u0432 \u0430\u043f\u0440\u0435\u043b\u0435. \u041a\u0430\u043a \u043e\u0442\u043c\u0435\u0447\u0430\u0435\u0442 Bloomberg, \u000d\u000a\u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442 \u0441\u0438\u0441\u0442\u0435\u043c\u0443 \u043c\u043e\u043d\u0438\u0442\u043e\u0440\u0438\u043d\u0433\u0430 \u000d\u000a\u0438 \u0440\u0430\u043d\u043d\u0435\u0433\u043e \u043f\u0440\u0435\u0434\u0443\u043f\u0440\u0435\u0436\u0434\u0435\u043d\u0438\u044f \u0441\u0438\u0442\u0443\u0430\u0446\u0438\u0439, \u000d\u000a\u0443\u0433\u0440\u043e\u0436\u0430\u044e\u0449\u0438\u0445 \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0430\u043c \u0436\u0438\u0437\u043d\u0435\u043d\u043d\u043e \u0432\u0430\u0436\u043d\u044b\u0445 \u000d\u000a\u0442\u043e\u0432\u0430\u0440\u043e\u0432. \u000a\u000d\u000a\u0412 \u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u0438 \u0437\u0430\u0440\u0443\u0431\u0435\u0436\u043d\u044b\u0445 \u0441\u0442\u0440\u0430\u043d \u0438 \u043e\u0440\u0433\u0430\u043d\u0438\u0437\u0430\u0446\u0438\u0439, \u000d\u000a\u0432\u0432\u043e\u0434\u044f\u0449\u0438\u0445 \u0434\u0438\u0441\u043a\u0440\u0438\u043c\u0438\u043d\u0430\u0446\u0438\u043e\u043d\u043d\u044b\u0435 \u0437\u0430\u043f\u0440\u0435\u0442\u044b \u043f\u0440\u043e\u0442\u0438\u0432 \u000d\u000a\u041a\u0438\u0442\u0430\u044f, \u043c\u043e\u0433\u0443\u0442 \u043d\u0430\u0447\u0430\u0442\u044c \u0440\u0430\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u043d\u0438\u0435 \u0438 \u043f\u0440\u0438\u043d\u044f\u0442\u044c \u000d\u000a\u043c\u0435\u0440\u044b \u043f\u0440\u043e\u0442\u0438\u0432\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044f: \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0438\u0442\u044c \u0438\u043c\u043f\u043e\u0440\u0442 \u000d\u000a\u0438 \u044d\u043a\u0441\u043f\u043e\u0440\u0442 \u0442\u043e\u0432\u0430\u0440\u043e\u0432, \u0443\u0441\u043b\u0443\u0433 \u0438 \u0442\u0435\u0445\u043d\u043e\u043b\u043e\u0433\u0438\u0439, \u0432\u0432\u0435\u0441\u0442\u0438 \u000d\u000a\u0441\u043f\u0435\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u0435 \u0442\u0430\u0440\u0438\u0444\u044b. \u042e\u0440\u0438\u0434\u0438\u0447\u0435\u0441\u043a\u0438\u043c \u000d\u000a\u0438 \u0444\u0438\u0437\u0438\u0447\u0435\u0441\u043a\u0438\u043c \u043b\u0438\u0446\u0430\u043c \u043c\u043e\u0433\u0443\u0442 \u0437\u0430\u043f\u0440\u0435\u0442\u0438\u0442\u044c \u0432\u044a\u0435\u0437\u0434, \u000d\u000a\u0438\u043d\u0432\u0435\u0441\u0442\u0438\u0446\u0438\u0438, \u0430 \u0442\u0430\u043a\u0436\u0435 \u043b\u044e\u0431\u044b\u0435 \u0441\u0434\u0435\u043b\u043a\u0438 \u0432 \u041a\u041d\u0420. \u000a\u000d\u000a\u041e\u0442\u0434\u0435\u043b\u044c\u043d\u043e \u043f\u0440\u043e\u043f\u0438\u0441\u0430\u043d\u0430 \u0431\u043e\u0440\u044c\u0431\u0430 \u0441 \u043d\u0435\u0437\u0430\u043a\u043e\u043d\u043d\u044b\u043c \u000d\u000a\u0441\u0431\u043e\u0440\u043e\u043c \u0438\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0438\u0438, \u043e\u0434\u043d\u0430\u043a\u043e \u0447\u0442\u043e \u0432 \u043d\u0435\u0433\u043e \u0432\u0445\u043e\u0434\u0438\u0442, \u000d\u000a\u043d\u0435 \u043f\u043e\u044f\u0441\u043d\u044f\u0435\u0442\u0441\u044f. \u0422\u0430\u043a\u0438\u043c \u043e\u0431\u0440\u0430\u0437\u043e\u043c, \u041a\u0438\u0442\u0430\u0439 \u000d\u000a\u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0430\u0435\u0442 \u0441\u043e\u0432\u0435\u0440\u0448\u0435\u043d\u0441\u0442\u0432\u043e\u0432\u0430\u0442\u044c \u043c\u0435\u0440\u044b \u000d\u000a\u043f\u043e \u043f\u0440\u043e\u0442\u0438\u0432\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u044e \u0442\u043e\u0440\u0433\u043e\u0432\u044b\u043c \u0432\u043e\u0439\u043d\u0430\u043c \u000d\u000a\u0438 \u0441\u0430\u043d\u043a\u0446\u0438\u043e\u043d\u043d\u043e\u043c\u0443 \u0434\u0430\u0432\u043b\u0435\u043d\u0438\u044e, \u043f\u0440\u0435\u0436\u0434\u0435 \u0432\u0441\u0435\u0433\u043e \u000d\u000a\u0441\u043e \u0441\u0442\u043e\u0440\u043e\u043d\u044b \u0421\u0428\u0410.\u000d\u000a09 09"]